-- SOURCE: 20261005010000_traffic_detail_suggestions.sql
-- Read-only, bounded name suggestions. Uses caller privileges and existing RLS.
-- No tables, data rewrites, or privilege elevation.
create or replace function public.traffic_reference_name(p_data jsonb)
returns text language plpgsql immutable security invoker set search_path = pg_catalog as $$
declare v jsonb := p_data; s text; k text;
begin
  if jsonb_typeof(v) = 'string' then
    s := btrim(v #>> '{}');
    if left(s,1) in ('{','[') then
      begin v := s::jsonb; exception when invalid_text_representation then return s; end;
    else return s; end if;
  end if;
  foreach k in array array['Name','name','Назва','Текст','text','ПІБ'] loop
    if jsonb_typeof(v->k) in ('string','number') then
      s := btrim(v->>k);
      if s <> '' then return s; end if;
    end if;
  end loop;
  return null;
end $$;



create or replace function public.traffic_detail_suggestions(p_query text, p_offset integer default 0)
returns jsonb language sql stable security invoker set search_path = pg_catalog, public as $$
  with matches as (
    select d.detail_id, public.traffic_reference_name(to_jsonb(d.data)) as name
    from public.details d
  ), page as (
    select detail_id, name from matches
    where name is not null and strpos(lower(name), lower(btrim(coalesce(p_query,'')))) > 0
    order by name, detail_id
    offset greatest(coalesce(p_offset,0),0) limit 21
  )
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(to_jsonb(x)) from
      (select * from page order by name, detail_id limit 20) x), '[]'::jsonb),
    'has_more', (select count(*) > 20 from page)
  );
$$;

-- Exact case-insensitive reference lookup; historic duplicates keep their IDs.
-- Prefer exact spelling, then the oldest stable ID, matching existing lookup intent.
create or replace function public.traffic_reference_id(p_kind text, p_name text)
returns bigint language plpgsql stable security invoker set search_path = pg_catalog, public as $$
declare result bigint;
begin
  if nullif(btrim(p_name),'') is null then return null; end if;
  if p_kind = 'details' then
    select d.detail_id into result from public.details d
    where regexp_replace(lower(btrim(public.traffic_reference_name(to_jsonb(d.data)))), '[[:space:]]+', ' ', 'g') = regexp_replace(lower(btrim(p_name)), '[[:space:]]+', ' ', 'g')
    order by (public.traffic_reference_name(to_jsonb(d.data)) = btrim(p_name)) desc, d.detail_id limit 1;
  elsif p_kind = 'shops' then
    select s.shop_id into result from public.shops s
    where regexp_replace(lower(btrim(public.traffic_reference_name(to_jsonb(s.data)))), '[[:space:]]+', ' ', 'g') = regexp_replace(lower(btrim(p_name)), '[[:space:]]+', ' ', 'g')
    order by (public.traffic_reference_name(to_jsonb(s.data)) = btrim(p_name)) desc, s.shop_id limit 1;
  else raise exception 'Unsupported reference'; end if;
  return result;
end $$;

create or replace function public.traffic_reference_ids(p_items jsonb)
returns jsonb language plpgsql stable security invoker set search_path = pg_catalog, public as $$
begin
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 100 then
    raise exception 'Expected at most 100 names';
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('kind', x->>'kind', 'name', x->>'name',
    'id', public.traffic_reference_id(x->>'kind', x->>'name'))) from jsonb_array_elements(p_items) x), '[]'::jsonb);
end $$;


-- SOURCE: 20261005100000_traffic_service_book.sql
-- Additive read-only API. Uses the caller's existing table permissions and RLS.

create or replace function public.sto_read_object_v1(p_value jsonb)
returns jsonb language plpgsql immutable security invoker
set search_path = pg_catalog
as $$
declare parsed jsonb;
begin
  if jsonb_typeof(p_value) = 'object' then return p_value; end if;
  if jsonb_typeof(p_value) = 'string' then
    begin
      parsed := (p_value #>> '{}')::jsonb;
      if jsonb_typeof(parsed) = 'object' then return parsed; end if;
    exception when invalid_text_representation then return '{}'::jsonb;
    end;
  end if;
  return '{}'::jsonb;
end;
$$;

create or replace function public.sto_service_book_search_v1(
  p_query text, p_after bigint default null
) returns jsonb language sql stable security invoker
set search_path = pg_catalog, public
as $$
  with candidates as (
    select c.cars_id, c.client_id,
      public.sto_read_object_v1(c.data::jsonb) as car_data,
      public.sto_read_object_v1(cl.data::jsonb) as client_data
    from public.cars c
    left join public.clients cl on cl.client_id = c.client_id
    where c.is_deleted is not true
      and (p_after is null or c.cars_id > p_after)
  ), page as (
    select * from candidates
    where length(btrim(coalesce(p_query, ''))) > 0
      and exists (
        select 1 from unnest(array[
          car_data->>'Авто', car_data->>'Номер авто', car_data->>'Vincode',
          car_data->>'КодДВЗ', client_data->>'ПІБ', client_data->>'Телефон'
        ]) as value(text_value)
        where strpos(lower(coalesce(text_value, '')), lower(btrim(p_query))) > 0
      )
    order by cars_id limit 21
  ), visible as (select * from page order by cars_id limit 20)
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'car', jsonb_build_object('cars_id', cars_id, 'client_id', client_id, 'data', car_data),
      'client', jsonb_build_object('client_id', client_id, 'data', client_data)
    ) order by cars_id) from visible), '[]'::jsonb),
    'has_more', (select count(*) > 20 from page),
    'next_cursor', (select max(cars_id) from visible)
  );
$$;

revoke all on function public.sto_read_object_v1(jsonb) from public;
revoke all on function public.sto_service_book_search_v1(text,bigint) from public;
grant execute on function public.sto_read_object_v1(jsonb) to anon, authenticated;
grant execute on function public.sto_service_book_search_v1(text,bigint) to anon, authenticated;


-- SOURCE: 20261005110000_traffic_act_read_models.sql
-- Requires 20261005100000_traffic_service_book.sql (JSON compatibility helper).
-- Read models only: never use these partial documents for saving or offline editing.

create or replace function public.sto_act_list_data_v1(p_data jsonb)
returns jsonb language sql immutable security invoker
set search_path = pg_catalog, public
as $$
  with d as (select public.sto_read_object_v1(p_data) as value)
  select case when p_data is null or p_data in ('null'::jsonb, '""'::jsonb, 'false'::jsonb, '0'::jsonb)
    then p_data else coalesce((select jsonb_object_agg(key, value) from jsonb_each(d.value)
    where key = any(array['Номер авто','Держ. номер','Автомобіль','Авто','Марка',
      'Загальна сума','total','amount','Знижка','За деталі','За роботу','Дзвінок',
      'Примітки','Рекомендації','Причина звернення','Заморожений'])), '{}'::jsonb)
    || jsonb_build_object(
      'Роботи', coalesce((select jsonb_agg(jsonb_build_object(
        'Робота', w->'Робота', 'Назва', w->'Назва', 'Слюсар', w->'Слюсар'))
        from jsonb_array_elements(case when jsonb_typeof(d.value->'Роботи')='array'
          then d.value->'Роботи' else '[]'::jsonb end) w), '[]'::jsonb),
      'Деталі', coalesce((select jsonb_agg(jsonb_build_object(
        'Деталь', w->'Деталь', 'Назва', w->'Назва'))
        from jsonb_array_elements(case when jsonb_typeof(d.value->'Деталі')='array'
          then d.value->'Деталі' else '[]'::jsonb end) w), '[]'::jsonb)
    ) end from d;
$$;

create or replace function public.sto_act_list_page_v1(
  p_from timestamptz default null, p_to timestamptz default null,
  p_mode text default null, p_before bigint default null
) returns jsonb language sql stable security invoker
set search_path = pg_catalog, public
as $$
  with page as (
    select a.* from public.acts a
    where (p_before is null or a.act_id < p_before)
      and case p_mode
        when 'open' then a.date_off is null
        when 'closed' then a.date_off is not null
        when 'frozen' then true
        else p_from is not null and p_to is not null and a.date_on >= p_from and a.date_on <= p_to
      end
    order by a.act_id desc limit 201
  ), visible as (select * from page order by act_id desc limit 200)
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(
      (to_jsonb(a) - 'data' - 'info' - 'details') || jsonb_build_object(
        'data', public.sto_act_list_data_v1(a.data::jsonb),
        '__sto_projection', 'act-list-v1'
      ) || case when to_jsonb(a)->>'info' is not null then jsonb_build_object(
        'info', public.sto_act_list_data_v1(to_jsonb(a)->'info')) else '{}'::jsonb end
        || case when to_jsonb(a)->>'details' is not null then jsonb_build_object(
        'details', public.sto_act_list_data_v1(to_jsonb(a)->'details')) else '{}'::jsonb end
      order by a.act_id desc) from visible a), '[]'::jsonb),
    'has_more', (select count(*) > 200 from page),
    'next_cursor', (select min(act_id) from visible)
  );
$$;

create or replace function public.sto_previous_recommendations_v1(
  p_car_id bigint, p_exclude_act bigint, p_before bigint default null
) returns jsonb language sql stable security invoker
set search_path = pg_catalog, public
as $$
  with page as (
    select a.act_id, a.cars_id, a.date_off, a.pruimalnyk,
      public.sto_read_object_v1(a.data::jsonb) as d
    from public.acts a where a.cars_id = p_car_id and a.act_id <> p_exclude_act
      and (p_before is null or a.act_id < p_before)
    order by a.act_id desc limit 201
  ), visible as (select * from page order by act_id desc limit 200)
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'act_id', act_id, 'cars_id', cars_id, 'date_off', date_off, 'pruimalnyk', pruimalnyk,
      'data', jsonb_build_object('Рекомендації', d->'Рекомендації',
        'Заморожений', d->'Заморожений') || case when d ? '__workshop_v1'
          then jsonb_build_object('__workshop_v1', d->'__workshop_v1') else '{}'::jsonb end
      ) order by act_id desc) from visible), '[]'::jsonb),
    'has_more', (select count(*) > 200 from page),
    'next_cursor', (select min(act_id) from visible)
  );
$$;

create or replace function public.sto_act_attention_page_v1(
  p_after bigint default null, p_reception text default null
) returns jsonb language sql stable security invoker
set search_path = pg_catalog, public
as $$
  with page as (
    select a.act_id, a.date_on, a.date_off, a.pruimalnyk, a."slusarsOn",
      public.sto_read_object_v1(a.data::jsonb) as d
    from public.acts a
    where (p_after is null or a.act_id > p_after)
      and (p_reception is null or a.pruimalnyk = p_reception)
    order by a.act_id limit 201
  ), visible as (select * from page order by act_id limit 200)
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'act_id', act_id, 'date_on', date_on, 'date_off', date_off,
      'pruimalnyk', pruimalnyk, 'slusarsOn', "slusarsOn",
      'data', jsonb_build_object(
        'Заморожений', d->'Заморожений', '__payroll_pending', d->'__payroll_pending',
        'Роботи', coalesce((select jsonb_agg(jsonb_build_object(
          'Робота', w->'Робота', 'Слюсар', w->'Слюсар', 'Ціна', w->'Ціна'))
          from jsonb_array_elements(case when jsonb_typeof(d->'Роботи')='array'
            then d->'Роботи' else '[]'::jsonb end) w), '[]'::jsonb),
        'Деталі', coalesce((select jsonb_agg(jsonb_build_object(
          'Деталь', w->'Деталь', 'Ціна', w->'Ціна'))
          from jsonb_array_elements(case when jsonb_typeof(d->'Деталі')='array'
            then d->'Деталі' else '[]'::jsonb end) w), '[]'::jsonb)
      ) || case when d ? '__workshop_v1' then jsonb_build_object(
        '__workshop_v1', d->'__workshop_v1') else '{}'::jsonb end
    ) order by act_id) from visible), '[]'::jsonb),
    'has_more', (select count(*) > 200 from page),
    'next_cursor', (select max(act_id) from visible)
  );
$$;

revoke all on function public.sto_act_attention_page_v1(bigint,text) from public;
grant execute on function public.sto_act_attention_page_v1(bigint,text) to anon, authenticated;
revoke all on function public.sto_act_list_data_v1(jsonb) from public;
revoke all on function public.sto_act_list_page_v1(timestamptz,timestamptz,text,bigint) from public;
revoke all on function public.sto_previous_recommendations_v1(bigint,bigint,bigint) from public;
grant execute on function public.sto_act_list_data_v1(jsonb) to anon, authenticated;
grant execute on function public.sto_act_list_page_v1(timestamptz,timestamptz,text,bigint) to anon, authenticated;
grant execute on function public.sto_previous_recommendations_v1(bigint,bigint,bigint) to anon, authenticated;


-- SOURCE: 20261005130000_traffic_reports.sql
-- Narrow accounting read contract. No tables, writes, or privilege escalation.
create or replace function public.traffic_json_object(p_value jsonb)
returns jsonb language plpgsql immutable security invoker set search_path = public
as $$
begin
  if jsonb_typeof(p_value) = 'string' then
    p_value := (p_value #>> '{}')::jsonb;
  end if;
  if jsonb_typeof(p_value) = 'object' then return p_value; end if;
  return '{}'::jsonb;
exception when invalid_text_representation then
  return '{}'::jsonb;
end;
$$;

create or replace function public.traffic_accounting_statuses(p_ids bigint[] default null, p_after bigint default null, p_limit integer default 200)
returns jsonb language sql stable security invoker set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'act_id', q.act_id, 'date_off', q.date_off, 'rosraxovano', q.rosraxovano,
    'data', jsonb_build_object('Заморожений', q.body->'Заморожений',
      '__payroll_pending', q.body->'__payroll_pending', 'Знижка', q.body->'Знижка')
  ) order by q.act_id), '[]'::jsonb)
  from (
    select a.act_id, a.date_off, a.rosraxovano,
      public.traffic_json_object(a.data::jsonb) as body
    from public.acts a
    where (p_ids is null or a.act_id = any(p_ids)) and (p_after is null or a.act_id > p_after)
    order by a.act_id limit greatest(1, least(coalesce(p_limit, 200), 200))
  ) q;
$$;
-- The existing custom employee login can use the anon database role. INVOKER
-- preserves that role's existing table grants/RLS; this does not bypass them.
revoke all on function public.traffic_accounting_statuses(bigint[],bigint,integer) from public;
grant execute on function public.traffic_accounting_statuses(bigint[],bigint,integer) to anon, authenticated;

