-- Search before transfer; only fields actually used by Atlas lookup cards.
-- Search normalization is supplied by the existing UI parser, not guessed here.
create or replace function public.traffic_ai_lookup(
  p_names text[] default '{}', p_phone text default '', p_brand text default '',
  p_plate text default '', p_vin text default '', p_limit integer default 50)
returns jsonb language sql stable security invoker set search_path = public
as $$
  with clients as (
    select c.client_id, public.traffic_json_object(c.data::jsonb) d from public.clients c
  ), cars as (
    select c.cars_id, c.client_id, public.traffic_json_object(c.data::jsonb) d
    from public.cars c where c.is_deleted is not true
  ), direct_clients as (
    select c.* from clients c where
      (cardinality(coalesce(p_names,'{}')) = 0 and p_phone = '' and p_brand = '' and p_plate = '' and p_vin = '') or
      exists (select 1 from unnest(p_names) n where n <> '' and
        position(lower(n) in lower(coalesce(nullif(c.d->>'ПІБ',''),c.d->>'Клієнт',''))) > 0)
      or (p_phone <> '' and (position(p_phone in regexp_replace(coalesce(c.d->>'Телефон',''),'[^0-9]','','g')) > 0
        or position(p_phone in regexp_replace(coalesce(c.d->>'Додатковий',''),'[^0-9]','','g')) > 0))
  ), matched_cars as (
    select c.* from cars c where
      (cardinality(coalesce(p_names,'{}')) = 0 and p_phone = '' and p_brand = '' and p_plate = '' and p_vin = '') or
      (p_brand <> '' and position(lower(p_brand) in lower(coalesce(c.d->>'Авто',''))) > 0)
      or (p_plate <> '' and position(p_plate in regexp_replace(translate(upper(coalesce(c.d->>'Номер авто','')),
        'АВЕКМНОРСТУХІЇ','ABEKMHOPCTYXII'),'[^A-Z0-9]','','g')) > 0)
      or (p_vin <> '' and position(p_vin in regexp_replace(translate(upper(coalesce(nullif(c.d->>'Vincode',''),c.d->>'VIN','')),
        'АВЕКМНОРСТУХІЇ','ABEKMHOPCTYXII'),'[^A-Z0-9]','','g')) > 0)
      or c.client_id in (select client_id from direct_clients)
  ), matched_clients as (
    select c.* from clients c where c.client_id in (select client_id from direct_clients)
      or c.client_id in (select client_id from matched_cars)
  ), client_page as (
    select * from matched_clients order by client_id limit greatest(1,least(coalesce(p_limit,50),200))
  ), car_page as (
    select * from matched_cars order by cars_id limit greatest(1,least(coalesce(p_limit,50),200))
  )
  select jsonb_build_object(
    'clients', coalesce((select jsonb_agg(jsonb_build_object('client_id',c.client_id,'data',
      (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(c.d)
       where key = any(array['ПІБ','Клієнт','Телефон','Джерело','Додаткові','Додатковий']))) order by c.client_id) from client_page c),'[]'::jsonb),
    'cars', coalesce((select jsonb_agg(jsonb_build_object('cars_id',c.cars_id,'client_id',c.client_id,'data',
      (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(c.d)
       where key = any(array['Авто','Номер авто','Vincode','VIN','Рік','Обʼєм','Об''єм','Пальне','КодДВЗ']))) order by c.cars_id) from car_page c),'[]'::jsonb),
    'clientCount',(select count(*) from matched_clients), 'carCount',(select count(*) from matched_cars)
  );
$$;
revoke all on function public.traffic_ai_lookup(text[],text,text,text,text,integer) from public;
grant execute on function public.traffic_ai_lookup(text[],text,text,text,text,integer) to anon, authenticated;



-- SOURCE: 20261006010000_traffic_stock_directory.sql
-- Compact stock form directories; preserves caller privileges and existing RLS.
-- Requires 20261005010000_traffic_detail_suggestions.sql. No tables or data changes.
create or replace function public.traffic_stock_staff_data(p_data jsonb)
returns jsonb language plpgsql immutable security invoker set search_path = pg_catalog as $$
declare v jsonb := p_data;
begin
  if jsonb_typeof(v) = 'string' then
    begin v := (v #>> '{}')::jsonb; exception when invalid_text_representation then return '{}'::jsonb; end;
  end if;
  return jsonb_strip_nulls(jsonb_build_object(
    'Name', v->'Name', 'name', v->'name', 'Ім''я', v->'Ім''я',
    'Доступ', v->'Доступ', 'доступ', v->'доступ'));
end $$;

create or replace function public.traffic_stock_directory(p_kind text, p_offset integer default 0)
returns jsonb language plpgsql stable security invoker set search_path = pg_catalog, public as $$
declare rows jsonb;
begin
  if p_kind = 'staff' then
    select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) into rows from (
      select s.slyusar_id, public.traffic_stock_staff_data(to_jsonb(s.data)) as data
      from public.slyusars s order by s.slyusar_id
      offset greatest(coalesce(p_offset,0),0) limit 501
    ) x;
  elsif p_kind = 'details' then
    select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) into rows from (
      select d.detail_id, public.traffic_reference_name(to_jsonb(d.data)) as name
      from public.details d order by d.detail_id
      offset greatest(coalesce(p_offset,0),0) limit 501
    ) x;
  elsif p_kind = 'shops' then
    select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) into rows from (
      select s.shop_id, public.traffic_reference_name(to_jsonb(s.data)) as name
      from public.shops s order by s.shop_id
      offset greatest(coalesce(p_offset,0),0) limit 501
    ) x;
  elsif p_kind = 'catalogs' then
    select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) into rows from (
      select distinct btrim(s.part_number::text) as part_number, btrim(s.name::text) as name
      from public.sclad s where nullif(btrim(s.part_number::text),'') is not null
      order by part_number, name
      offset greatest(coalesce(p_offset,0),0) limit 501
    ) x;
  else raise exception 'Unsupported stock directory'; end if;
  return jsonb_build_object('items', (select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb)
    from jsonb_array_elements(rows) with ordinality where ordinality <= 500),
    'has_more', jsonb_array_length(rows) > 500);
end $$;


-- SOURCE: 20261006020000_traffic_export_pages.sql
-- Verified export: first pass returns canonical text, second only its SHA-256.
-- SECURITY INVOKER retains the same table privileges and RLS as direct reads.

create or replace function public.traffic_export_page(
  p_table text, p_keys text[], p_offset integer default 0,
  p_limit integer default 250, p_hash_only boolean default false
) returns jsonb language plpgsql stable security invoker
set search_path = pg_catalog, public
as $$
declare ordering text; payload text; row_count integer; total bigint; k text;
begin
  if p_table is null or not (p_table = any(array[
    'acts','clients','cars','sclad','works','details','shops','slyusars','settings',
    'incomes','vutratu','faktura','post_arxiv','post_category','post_name','sms','whitelist',
    'act_changes_notifications','slusar_complete_notifications','audit_logs','ai_chats',
    'ai_messages','ai_skills','atlas_reminder_logs','atlas_reminders','atlas_telegram_users'
  ])) then raise exception 'Unsupported export table'; end if;
  if p_offset is null or p_offset < 0 or p_limit is null or p_limit < 1 or p_limit > 250 then
    raise exception 'Invalid export page';
  end if;
  if coalesce(cardinality(p_keys),0) = 0 then raise exception 'Export ordering is required'; end if;
  foreach k in array p_keys loop
    if k is null or not exists (select 1 from pg_attribute
      where attrelid = format('public.%I',p_table)::regclass and attname = k
        and attnum > 0 and not attisdropped) then raise exception 'Unknown export key'; end if;
  end loop;
  select string_agg(format('%I asc', key), ',') into ordering from unnest(p_keys) key;
  execute format(
    'with page as (select * from public.%I order by %s offset $1 limit $2)
     select coalesce(jsonb_agg(to_jsonb(page) order by %s),''[]''::jsonb)::text,
       count(*)::integer, (select count(*) from public.%I) from page',
    p_table, ordering, ordering, p_table
  ) into payload, row_count, total using p_offset, p_limit;
  return jsonb_build_object('format','sto-canonical-page-v1',
    'payload', case when p_hash_only then null else payload end,
    'count',row_count,'total',total,'hash',encode(sha256(convert_to(payload,'UTF8')),'hex'));
end;
$$;
revoke all on function public.traffic_export_page(text,text[],integer,integer,boolean) from public;
grant execute on function public.traffic_export_page(text,text[],integer,integer,boolean) to authenticated;


-- SOURCE: 20261006030000_traffic_invoice_origins.sql
create or replace function public.traffic_invoice_origins(p_origins text[])
returns jsonb language plpgsql stable security invoker
set search_path = pg_catalog, public
as $$
begin
  if coalesce(cardinality(p_origins),0) > 100 then raise exception 'Too many invoice origins'; end if;
  return coalesce((select jsonb_agg(origin) from (
    select distinct origin from unnest(p_origins) origin
    where nullif(origin,'') is not null and exists (
      select 1 from public.sclad s where strpos(coalesce(s.prumitka,''), origin) > 0
    )
  ) found), '[]'::jsonb);
end;
$$;
revoke all on function public.traffic_invoice_origins(text[]) from public;
grant execute on function public.traffic_invoice_origins(text[]) to authenticated;


-- SOURCE: 20261006040000_traffic_analytics.sql
-- Analytics reads only; existing financial formulas remain in the browser.
-- Requires 20261005130000_traffic_reports.sql. No tables or writes.
create or replace function public.traffic_analytics_acts(p_after bigint default null)
returns jsonb language sql stable security invoker set search_path = public
as $$
  with candidates as (
    select a.act_id, to_jsonb(a) as row_data,
      public.traffic_json_object(a.data::jsonb) as body
    from public.acts a
    where p_after is null or a.act_id > p_after
    order by a.act_id limit 201
  ), page as (
    select * from candidates order by act_id limit 200
  )
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(
      (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb)
       from jsonb_each(p.row_data) where key = any(array[
         'act_id','date_on','date_off','rosraxovano','avans','tupOplatu','client_id','cars_id'
       ])) || jsonb_build_object('data',
         (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb)
          from jsonb_each(p.body) where key = any(array[
            'За роботу','За деталі','Прибуток за роботу','Прибуток за деталі',
            'Знижка','Заморожений','Роботи','Деталі'
          ])), '__sto_projection','analytics-v1')
      order by p.act_id) from page p),'[]'::jsonb),
    'has_more', (select count(*) > 200 from candidates),
    'next_cursor', (select max(act_id) from page)
  );
$$;
revoke all on function public.traffic_analytics_acts(bigint) from public;
grant execute on function public.traffic_analytics_acts(bigint) to anon, authenticated;


-- SOURCE: 20261006050000_traffic_act_staff.sql
-- Read-only employee metadata and complete history entries for one act.
-- Never use this projection as the baseline for saving an employee document.
create or replace function public.traffic_act_staff(p_act_id bigint default null, p_after bigint default null)
returns jsonb language sql stable security invoker set search_path = public
as $$
  with candidates as (
    select s.slyusar_id, public.traffic_json_object(s.data::jsonb) as body
    from public.slyusars s
    where p_after is null or s.slyusar_id > p_after
    order by s.slyusar_id limit 201
  ), page as (select * from candidates order by slyusar_id limit 200)
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'slyusar_id', p.slyusar_id,
      'data', (p.body - 'Історія') || jsonb_build_object('Історія',
        coalesce((select jsonb_object_agg(day.key, entries.value)
          from jsonb_each(case when jsonb_typeof(p.body->'Історія')='object'
            then p.body->'Історія' else '{}'::jsonb end) day
          cross join lateral (
            select jsonb_agg(entry.value order by entry.ordinality) as value
            from jsonb_array_elements(case when jsonb_typeof(day.value)='array'
              then day.value else '[]'::jsonb end) with ordinality entry(value,ordinality)
            where p_act_id is not null and entry.value->>'Акт' = p_act_id::text
          ) entries
          where entries.value is not null),'{}'::jsonb)),
      '__sto_projection','act-staff-v1'
    ) order by p.slyusar_id) from page p),'[]'::jsonb),
    'has_more', (select count(*) > 200 from candidates),
    'next_cursor', (select max(slyusar_id) from page)
  );
$$;
revoke all on function public.traffic_act_staff(bigint,bigint) from public;
grant execute on function public.traffic_act_staff(bigint,bigint) to anon, authenticated;


-- SOURCE: 20261007010000_traffic_stock_shop_names.sql
-- Distinct supplier filter options from the stock itself, including historical
-- names absent from the shops directory. No trimming/renaming of stored values.
create or replace function public.traffic_stock_shop_names(p_offset integer default 0)
returns jsonb language sql stable security invoker set search_path = public
as $$
  with names as (
    select distinct to_jsonb(s.shops) as value from public.sclad s
    where s.shops is not null and s.shops::text <> ''
  ), page as (
    select value from names order by value
    offset greatest(coalesce(p_offset,0),0) limit 501
  )
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(jsonb_build_object('shops',value) order by value)
      from (select value from page order by value limit 500) visible),'[]'::jsonb),
    'has_more', (select count(*) > 500 from page)
  );
$$;
revoke all on function public.traffic_stock_shop_names(integer) from public;
grant execute on function public.traffic_stock_shop_names(integer) to anon, authenticated;


-- SOURCE: 20261007110000_traffic_stock_pages.sql
