$$;

create or replace function public.traffic_stock_page(p_status text default null,p_from text default null,p_to text default null,p_query text default '',p_before bigint default null)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 with page as (
 select n.sclad_id,n.time_on,n.shops,n.part_number,n.name,n.kilkist_on,n.price,n."scladNomer",n.rahunok,n.akt,n.unit_measurement,n.statys,n.prumitka,n.xto_zamovuv,n.client_price
 from public.sclad n
 where (case when p_status='Прибула' then n.statys is null when p_status in ('Замовити','Замовлено') then n.statys=p_status else n.statys in ('Замовити','Замовлено') end)
 and (nullif(p_from,'') is null or n.time_on >= nullif(p_from,'')::timestamptz)
 and (nullif(p_to,'') is null or n.time_on <= nullif(p_to,'')::timestamptz)
 and (p_before is null or n.sclad_id<p_before)
 and (nullif(btrim(p_query),'') is null or strpos(lower(coalesce(n.part_number,'')),lower(btrim(p_query)))>0 or
 (public.traffic_catalog_key(p_query)<>'' and strpos(public.traffic_catalog_key(n.part_number),public.traffic_catalog_key(p_query))>0))
 order by n.sclad_id desc limit 51
 ), visible as (select * from page order by sclad_id desc limit 50)
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(v) order by v.sclad_id desc) from visible v),'[]'::jsonb),
 'has_more',(select count(*)>50 from page),'next_cursor',(select min(sclad_id) from visible));
$$;


revoke all on function public.traffic_catalog_key(text) from public;
revoke all on function public.traffic_stock_page(text,text,text,text,bigint) from public;
grant execute on function public.traffic_catalog_key(text) to anon,authenticated;
grant execute on function public.traffic_stock_page(text,text,text,text,bigint) to anon,authenticated;


-- SOURCE: 20261007120000_traffic_client_form.sql
-- Bounded form suggestions; caller permissions/RLS remain in force.

create or replace function public.traffic_client_form_options(
  p_kind text, p_query text default '', p_after bigint default null,
  p_client bigint default null
) returns jsonb language plpgsql stable security invoker
set search_path = pg_catalog, public
as $$
declare result jsonb; field_name text;
begin
  if p_kind in ('client','phone') then
    field_name := case when p_kind='client' then 'ПІБ' else 'Телефон' end;
    with candidates as (
      select client_id as id, public.sto_read_object_v1(data::jsonb) as d
      from public.clients
      where (p_after is null or client_id > p_after)
        and (p_client is null or client_id=p_client)
    ), page as (
      select * from candidates where coalesce(d->>'ПІБ','') <> ''
        and (strpos(lower(coalesce(d->>field_name,'')),lower(coalesce(p_query,'')))>0
          or (p_kind='phone' and regexp_replace(coalesce(p_query,''),'[^0-9]','','g')<>''
            and strpos(regexp_replace(coalesce(d->>field_name,''),'[^0-9]','','g'),
              regexp_replace(p_query,'[^0-9]','','g'))>0))
      order by id limit 21
    ), visible as (select * from page order by id limit 20)
    select jsonb_build_object('items', coalesce((select jsonb_agg(jsonb_build_object(
      'id',id::text,'fullName',coalesce(d->>'ПІБ',''),'phone',coalesce(d->>'Телефон',''),
      'data',jsonb_build_object('ПІБ',d->'ПІБ','Телефон',d->'Телефон')) order by id) from visible),'[]'::jsonb),
      'has_more',(select count(*)>20 from page),'next_cursor',(select max(id) from visible)) into result;
  else
    field_name := case p_kind when 'carModel' then 'Авто' when 'carNumber' then 'Номер авто'
      when 'carCodeEdit' then 'КодДВЗ' when 'carEngineEdit' then 'Обʼєм'
      when 'carVinEdit' then 'Vincode' when 'carModelEdit' then 'Авто'
      when 'carNumberEdit' then 'Номер авто' else null end;
    if field_name is null then raise exception 'Unsupported form field'; end if;
    with candidates as (
      select cars_id as id, client_id, public.sto_read_object_v1(data::jsonb) as d
      from public.cars where is_deleted is not true
        and (p_after is null or cars_id>p_after) and (p_client is null or client_id=p_client)
    ), page as (
      select * from candidates where coalesce(d->>field_name,'') <> ''
        and strpos(lower(coalesce(d->>field_name,'')),lower(coalesce(p_query,'')))>0
      order by id limit 21
    ), visible as (select * from page order by id limit 20)
    select jsonb_build_object('items',coalesce((select jsonb_agg(
      jsonb_build_object('id',id::text,'client_id',client_id::text,'label',d->>field_name,
        'Авто',d->'Авто','Номер авто',d->'Номер авто') order by id) from visible),'[]'::jsonb),
      'has_more',(select count(*)>20 from page),'next_cursor',(select max(id) from visible)) into result;
  end if;
  return result;
end;
$$;
revoke all on function public.traffic_client_form_options(text,text,bigint,bigint) from public;
grant execute on function public.traffic_client_form_options(text,text,bigint,bigint) to anon, authenticated;


-- SOURCE: 20261007130000_traffic_service_history.sql

-- A chart reads financial operands only; visit pages additionally receive display fields.
-- Keep original JSON operands so browser fallback/rounding rules do not change.
create or replace function public.traffic_service_history_data(p_data jsonb,p_summary boolean)
returns jsonb language sql immutable security invoker set search_path=pg_catalog,public as $$
 with source as (select public.sto_read_object_v1(p_data) d)
 select coalesce((select jsonb_object_agg(key,value) from jsonb_each(d)
   where key=any(case when p_summary then array['Пробіг','За роботу','За деталі']
     else array['Пробіг','За роботу','За деталі','Заморожений','Рекомендації','Причина звернення','__workshop_v1'] end)), '{}'::jsonb)
   || jsonb_build_object('Роботи',coalesce((select jsonb_agg(
     (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(w) where key=any(
       case when p_summary then array['Кількість','Ціна'] else array['Робота','Кількість','Ціна'] end))
     order by ord) from jsonb_array_elements(case when jsonb_typeof(d->'Роботи')='array' then d->'Роботи' else '[]' end)
       with ordinality a(w,ord) where jsonb_typeof(w)='object'),'[]'::jsonb),
   'Деталі',coalesce((select jsonb_agg(
     (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(w) where key=any(
       case when p_summary then array['Кількість','Ціна'] else array['Деталь','Кількість','Ціна'] end))
     order by ord) from jsonb_array_elements(case when jsonb_typeof(d->'Деталі')='array' then d->'Деталі' else '[]' end)
       with ordinality a(w,ord) where jsonb_typeof(w)='object'),'[]'::jsonb))
 from source;
$$;
create or replace function public.traffic_service_history(
  p_car bigint, p_before jsonb default null, p_summary boolean default false
) returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 with page as (
   select act_id,date_on,date_off,client_id,cars_id,
     public.traffic_service_history_data(data::jsonb,p_summary) data
   from public.acts
   where cars_id=p_car and (p_before is null
     or (p_before->>'date_on' is null and date_on is not null)
     or (date_on is null and p_before->>'date_on' is null and act_id<(p_before->>'act_id')::bigint)
     or date_on<(p_before->>'date_on')::timestamptz
     or (date_on=(p_before->>'date_on')::timestamptz and act_id<(p_before->>'act_id')::bigint))
   order by date_on desc nulls first,act_id desc limit case when p_summary then 201 else 51 end
 ), visible as (select * from page order by date_on desc nulls first,act_id desc limit case when p_summary then 200 else 50 end)
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(v) order by v.date_on desc nulls first,v.act_id desc) from visible v),'[]'::jsonb),
   'has_more',(select count(*)>case when p_summary then 200 else 50 end from page),
   'next_cursor',(select jsonb_build_object('date_on',date_on,'act_id',act_id) from visible order by date_on asc nulls last,act_id asc limit 1));
$$;
revoke all on function public.traffic_service_history_data(jsonb,boolean) from public;
revoke all on function public.traffic_service_history(bigint,jsonb,boolean) from public;
grant execute on function public.traffic_service_history_data(jsonb,boolean) to anon,authenticated;
grant execute on function public.traffic_service_history(bigint,jsonb,boolean) to anon,authenticated;


-- SOURCE: 20261007140000_traffic_offline_pages.sql

-- Hashes are computed under the caller's table permissions/RLS. The hash is
-- a change detector, never an authorization token. Existing tables only.
create or replace function public.traffic_offline_page(
  p_resource text,p_after bigint default null,p_hash text default null
) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare id_field text; columns_sql text; condition_sql text; sort_sql text;
  payload jsonb; digest text; more boolean; next_id bigint;
begin
  case p_resource
    when 'acts' then id_field:='act_id'; columns_sql:='n.*';
    when 'clients' then id_field:='client_id'; columns_sql:='n.client_id,n.data';
    when 'cars' then id_field:='cars_id'; columns_sql:='n.cars_id,n.client_id,n.data,n.is_deleted';
    when 'works' then id_field:='work_id'; columns_sql:='n.work_id,n.data';
    when 'details' then id_field:='detail_id'; columns_sql:='n.detail_id,n.data';
    when 'slyusars' then id_field:='slyusar_id'; columns_sql:='n.slyusar_id,n.data';
    else raise exception 'Unsupported offline resource';
  end case;
  if p_resource='acts' then
    if p_after is not null then raise exception 'Act offline profile is the latest 200 open acts'; end if;
    condition_sql:='n.date_off is null and public.sto_read_object_v1(n.data::jsonb)->''Заморожений'' is distinct from ''true''::jsonb';
    sort_sql:=format('n.%I desc',id_field);
  else
    condition_sql:=format('($1 is null or n.%I>$1)',id_field);
    if p_resource='cars' then condition_sql:=condition_sql||' and n.is_deleted is not true'; end if;
    sort_sql:=format('n.%I asc',id_field);
  end if;
  execute format('with page as (select %s from public.%I n where %s order by %s limit %s),
    visible as (select * from page order by %I %s limit 200)
    select coalesce((select jsonb_agg(to_jsonb(v) order by v.%I %s) from visible v),''[]''::jsonb),
      (select count(*)>200 from page),(select max(%I) from visible)',
    columns_sql,p_resource,condition_sql,sort_sql,case when p_resource='acts' then 200 else 201 end,
    id_field,case when p_resource='acts' then 'desc' else 'asc' end,
    id_field,case when p_resource='acts' then 'desc' else 'asc' end,id_field)
    into payload,more,next_id using p_after;
  digest:=encode(sha256(convert_to(payload::text,'UTF8')),'hex');
  return jsonb_build_object('hash',digest,'items',case when digest=p_hash then null else payload end,
    'count',jsonb_array_length(payload),'has_more',more,'next_cursor',next_id);
end;
$$;
revoke all on function public.traffic_offline_page(text,bigint,text) from public;
grant execute on function public.traffic_offline_page(text,bigint,text) to anon,authenticated;


-- SOURCE: 20261007150000_traffic_stock_costs.sql

create or replace function public.traffic_stock_costs(p_ids bigint[])
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb;
begin
 if coalesce(cardinality(p_ids),0)>200 then raise exception 'At most 200 stock IDs'; end if;
 with source as (
   select n.sclad_id,to_jsonb(n) row_data,public.sto_read_object_v1(to_jsonb(n)->'data') legacy
   from public.sclad n where n.sclad_id=any(p_ids)
 ), projected as (
   select sclad_id,row_data,
     coalesce((select jsonb_object_agg(key,value) from jsonb_each(legacy)
       where key in ('sclad_id','price','scladNomer','xto_zamovuv')),'{}'::jsonb) data
   from source
 )
 select coalesce(jsonb_agg(jsonb_build_object('sclad_id',sclad_id,'price',row_data->'price',
   'scladNomer',row_data->'scladNomer','xto_zamovuv',row_data->'xto_zamovuv','data',
   case when jsonb_typeof(row_data->'data')='string' then
     case when legacy_valid is true then to_jsonb(data::text) else row_data->'data' end
     when jsonb_typeof(row_data->'data')='object' then data else row_data->'data' end)
   order by sclad_id),'[]'::jsonb) into result
 from (select *, public.sto_read_object_v1(row_data->'data')<>'{}'::jsonb as legacy_valid from projected) p;
 return result;
end;
$$;
revoke all on function public.traffic_stock_costs(bigint[]) from public;
grant execute on function public.traffic_stock_costs(bigint[]) to anon,authenticated;


-- SOURCE: 20261008010000_traffic_dashboard.sql

create or replace function public.traffic_dashboard_data(p_data jsonb)
returns jsonb language sql immutable security invoker set search_path=pg_catalog,public as $$
 with source as (select public.sto_read_object_v1(p_data) d)
 select coalesce((select jsonb_object_agg(key,value) from jsonb_each(d)
   where key in ('ПІБ','Клієнт','Марка','Модель','Приймальник','Прибуток за роботу','Прибуток за деталі')),'{}'::jsonb)
   || jsonb_build_object('Роботи',coalesce((select jsonb_agg(
      case when jsonb_typeof(w)='object' then (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb)
        from jsonb_each(w) where key in ('Ціна','Кількість')) else w end order by ord)
      from jsonb_array_elements(case when jsonb_typeof(d->'Роботи')='array' then d->'Роботи' else '[]' end) with ordinality a(w,ord)),'[]'::jsonb),
     'Деталі',coalesce((select jsonb_agg(
      case when jsonb_typeof(w)='object' then (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb)
        from jsonb_each(w) where key in ('Ціна','Кількість')) else w end order by ord)
      from jsonb_array_elements(case when jsonb_typeof(d->'Деталі')='array' then d->'Деталі' else '[]' end) with ordinality a(w,ord)),'[]'::jsonb))
 from source;
$$;
create or replace function public.traffic_dashboard_page(p_from timestamptz,p_to timestamptz,p_before bigint default null)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 with page as (
   select a.act_id,a.date_on,a.date_off,a.client_id,a.cars_id,
     public.traffic_dashboard_data(a.data::jsonb) data,
     jsonb_build_object('ПІБ',public.sto_read_object_v1(cl.data::jsonb)->'ПІБ',
       'Клієнт',public.sto_read_object_v1(cl.data::jsonb)->'Клієнт') __client_data,
     jsonb_build_object('Авто',public.sto_read_object_v1(c.data::jsonb)->'Авто',
       'Марка',public.sto_read_object_v1(c.data::jsonb)->'Марка',
       'Модель',public.sto_read_object_v1(c.data::jsonb)->'Модель') __car_data
   from public.acts a left join public.clients cl on cl.client_id=a.client_id
   left join public.cars c on c.cars_id=a.cars_id and c.is_deleted is not true
   where ((a.date_on>=p_from and a.date_on<p_to) or (a.date_off>=p_from and a.date_off<p_to))
     and (p_before is null or a.act_id<p_before)
   order by a.act_id desc limit 101
 ), visible as (select * from page order by act_id desc limit 100)
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(v) order by act_id desc) from visible v),'[]'::jsonb),
   'has_more',(select count(*)>100 from page),'next_cursor',(select min(act_id) from visible));
$$;
revoke all on function public.traffic_dashboard_data(jsonb) from public;
revoke all on function public.traffic_dashboard_page(timestamptz,timestamptz,bigint) from public;
grant execute on function public.traffic_dashboard_data(jsonb) to anon,authenticated;
grant execute on function public.traffic_dashboard_page(timestamptz,timestamptz,bigint) to anon,authenticated;


-- SOURCE: 20261008020000_traffic_editor_catalog.sql
-- Exact legacy editor catalogue lookup. Read only, caller RLS; no new tables.
create or replace function public.traffic_editor_catalog_key(p_text text)
returns text language sql immutable security invoker set search_path=pg_catalog as $$
 select regexp_replace(lower(normalize(coalesce(p_text,''),NFKD)), '[^0-9A-Za-zª²-³µ¹-º¼-¾À-ÖØ-öø-ˁˆ-ˑˠ-ˤˬˮͰ-ʹͶ-ͷͺ-ͽͿΆΈ-ΊΌΎ-ΡΣ-ϵϷ-ҁҊ-ԯԱ-Ֆՙՠ-ֈא-תׯ-ײؠ-ي٠-٩ٮ-ٯٱ-ۓەۥ-ۦۮ-ۼۿܐܒ-ܯݍ-ޥޱ߀-ߪߴ-ߵߺࠀ-ࠕࠚࠤࠨࡀ-ࡘࡠ-ࡪࡰ-ࢇࢉ-ࢎࢠ-ࣉऄ-हऽॐक़-ॡ०-९ॱ-ঀঅ-ঌএ-ঐও-নপ-রলশ-হঽৎড়-ঢ়য়-ৡ০-ৱ৴-৹ৼਅ-ਊਏ-ਐਓ-ਨਪ-ਰਲ-ਲ਼ਵ-ਸ਼ਸ-ਹਖ਼-ੜਫ਼੦-੯ੲ-ੴઅ-ઍએ-ઑઓ-નપ-રલ-ળવ-હઽૐૠ-ૡ૦-૯ૹଅ-ଌଏ-ଐଓ-ନପ-ରଲ-ଳଵ-ହଽଡ଼-ଢ଼ୟ-ୡ୦-୯ୱ-୷ஃஅ-ஊஎ-ஐஒ-கங-சஜஞ-டண-தந-பம-ஹௐ௦-௲అ-ఌఎ-ఐఒ-నప-హఽౘ-ౚౝౠ-ౡ౦-౯౸-౾ಀಅ-ಌಎ-ಐಒ-ನಪ-ಳವ-ಹಽೝ-ೞೠ-ೡ೦-೯ೱ-ೲഄ-ഌഎ-ഐഒ-ഺഽൎൔ-ൖ൘-ൡ൦-൸ൺ-ൿඅ-ඖක-නඳ-රලව-ෆ෦-෯ก-ะา-ำเ-ๆ๐-๙ກ-ຂຄຆ-ຊຌ-ຣລວ-ະາ-ຳຽເ-ໄໆ໐-໙ໜ-ໟༀ༠-༳ཀ-ཇཉ-ཬྈ-ྌက-ဪဿ-၉ၐ-ၕၚ-ၝၡၥ-ၦၮ-ၰၵ-ႁႎ႐-႙Ⴀ-ჅჇჍა-ჺჼ-ቈቊ-ቍቐ-ቖቘቚ-ቝበ-ኈኊ-ኍነ-ኰኲ-ኵኸ-ኾዀዂ-ዅወ-ዖዘ-ጐጒ-ጕጘ-ፚ፩-፼ᎀ-ᎏᎠ-Ᏽᏸ-ᏽᐁ-ᙬᙯ-ᙿᚁ-ᚚᚠ-ᛪᛮ-ᛸᜀ-ᜑᜟ-ᜱᝀ-ᝑᝠ-ᝬᝮ-ᝰក-ឳៗៜ០-៩៰-៹᠐-᠙ᠠ-ᡸᢀ-ᢄᢇ-ᢨᢪᢰ-ᣵᤀ-ᤞ᥆-ᥭᥰ-ᥴᦀ-ᦫᦰ-ᧉ᧐-᧚ᨀ-ᨖᨠ-ᩔ᪀-᪉᪐-᪙ᪧᬅ-ᬳᭅ-ᭌ᭐-᭙ᮃ-ᮠᮮ-ᯥᰀ-ᰣ᱀-᱉ᱍ-ᱽᲀ-ᲊᲐ-ᲺᲽ-Ჿᳩ-ᳬᳮ-ᳳᳵ-ᳶᳺᴀ-ᶿḀ-ἕἘ-Ἕἠ-ὅὈ-Ὅὐ-ὗὙὛὝὟ-ώᾀ-ᾴᾶ-ᾼιῂ-ῄῆ-ῌῐ-ΐῖ-Ίῠ-Ῥῲ-ῴῶ-ῼ⁰-ⁱ⁴-⁹ⁿ-₉ₐ-ₜℂℇℊ-ℓℕℙ-ℝℤΩℨK-ℭℯ-ℹℼ-ℿⅅ-ⅉⅎ⅐-↉①-⒛⓪-⓿❶-➓Ⰰ-ⳤⳫ-ⳮⳲ-ⳳ⳽ⴀ-ⴥⴧⴭⴰ-ⵧⵯⶀ-ⶖⶠ-ⶦⶨ-ⶮⶰ-ⶶⶸ-ⶾⷀ-ⷆⷈ-ⷎⷐ-ⷖⷘ-ⷞⸯ々-〇〡-〩〱-〵〸-〼ぁ-ゖゝ-ゟァ-ヺー-ヿㄅ-ㄯㄱ-ㆎ㆒-㆕ㆠ-ㆿㇰ-ㇿ㈠-㈩㉈-㉏㉑-㉟㊀-㊉㊱-㊿㐀-䶿一-ꒌꓐ-ꓽꔀ-ꘌꘐ-ꘫꙀ-ꙮꙿ-ꚝꚠ-ꛯꜗ-ꜟꜢ-ꞈꞋ-ꟍꟐ-ꟑꟓꟕ-Ƛꟲ-ꠁꠃ-ꠅꠇ-ꠊꠌ-ꠢ꠰-꠵ꡀ-ꡳꢂ-ꢳ꣐-꣙ꣲ-ꣷꣻꣽ-ꣾ꤀-ꤥꤰ-ꥆꥠ-ꥼꦄ-ꦲꧏ-꧙ꧠ-ꧤꧦ-ꧾꨀ-ꨨꩀ-ꩂꩄ-ꩋ꩐-꩙ꩠ-ꩶꩺꩾ-ꪯꪱꪵ-ꪶꪹ-ꪽꫀꫂꫛ-ꫝꫠ-ꫪꫲ-ꫴꬁ-ꬆꬉ-ꬎꬑ-ꬖꬠ-ꬦꬨ-ꬮꬰ-ꭚꭜ-ꭩꭰ-ꯢ꯰-꯹가-힣ힰ-ퟆퟋ-ퟻ豈-舘並-龎ﬀ-ﬆﬓ-ﬗיִײַ-ﬨשׁ-זּטּ-לּמּנּ-סּףּ-פּצּ-ﮱﯓ-ﴽﵐ-ﶏﶒ-ﷇﷰ-ﷻﹰ-ﹴﹶ-ﻼ０-９Ａ-Ｚａ-ｚｦ-ﾾￂ-ￇￊ-ￏￒ-ￗￚ-ￜ𐀀-𐀋𐀍-𐀦𐀨-𐀺𐀼-𐀽𐀿-𐁍𐁐-𐁝𐂀-𐃺𐄇-𐄳𐅀-𐅸𐆊-𐆋𐊀-𐊜𐊠-𐋐𐋡-𐋻𐌀-𐌣𐌭-𐍊𐍐-𐍵𐎀-𐎝𐎠-𐏃𐏈-𐏏𐏑-𐏕𐐀-𐒝𐒠-𐒩𐒰-𐓓𐓘-𐓻𐔀-𐔧𐔰-𐕣𐕰-𐕺𐕼-𐖊𐖌-𐖒𐖔-𐖕𐖗-𐖡𐖣-𐖱𐖳-𐖹𐖻-𐖼𐗀-𐗳𐘀-𐜶𐝀-𐝕𐝠-𐝧𐞀-𐞅𐞇-𐞰𐞲-𐞺𐠀-𐠅𐠈𐠊-𐠵𐠷-𐠸𐠼𐠿-𐡕𐡘-𐡶𐡹-𐢞𐢧-𐢯𐣠-𐣲𐣴-𐣵𐣻-𐤛𐤠-𐤹𐦀-𐦷𐦼-𐧏𐧒-𐨀𐨐-𐨓𐨕-𐨗𐨙-𐨵𐩀-𐩈𐩠-𐩾𐪀-𐪟𐫀-𐫇𐫉-𐫤𐫫-𐫯𐬀-𐬵𐭀-𐭕𐭘-𐭲𐭸-𐮑𐮩-𐮯𐰀-𐱈𐲀-𐲲𐳀-𐳲𐳺-𐴣𐴰-𐴹𐵀-𐵥𐵯-𐶅𐹠-𐹾𐺀-𐺩𐺰-𐺱𐻂-𐻄𐼀-𐼧𐼰-𐽅𐽑-𐽔𐽰-𐾁𐾰-𐿋𐿠-𐿶𑀃-𑀷𑁒-𑁯𑁱-𑁲𑁵𑂃-𑂯𑃐-𑃨𑃰-𑃹𑄃-𑄦𑄶-𑄿𑅄𑅇𑅐-𑅲𑅶𑆃-𑆲𑇁-𑇄𑇐-𑇚𑇜𑇡-𑇴𑈀-𑈑𑈓-𑈫𑈿-𑉀𑊀-𑊆𑊈𑊊-𑊍𑊏-𑊝𑊟-𑊨𑊰-𑋞𑋰-𑋹𑌅-𑌌𑌏-𑌐𑌓-𑌨𑌪-𑌰𑌲-𑌳𑌵-𑌹𑌽𑍐𑍝-𑍡𑎀-𑎉𑎋𑎎𑎐-𑎵𑎷𑏑𑏓𑐀-𑐴𑑇-𑑊𑑐-𑑙𑑟-𑑡𑒀-𑒯𑓄-𑓅𑓇𑓐-𑓙𑖀-𑖮𑗘-𑗛𑘀-𑘯𑙄𑙐-𑙙𑚀-𑚪𑚸𑛀-𑛉𑛐-𑛣𑜀-𑜚𑜰-𑜻𑝀-𑝆𑠀-𑠫𑢠-𑣲𑣿-𑤆𑤉𑤌-𑤓𑤕-𑤖𑤘-𑤯𑤿𑥁𑥐-𑥙𑦠-𑦧𑦪-𑧐𑧡𑧣𑨀𑨋-𑨲𑨺𑩐𑩜-𑪉𑪝𑪰-𑫸𑯀-𑯠𑯰-𑯹𑰀-𑰈𑰊-𑰮𑱀𑱐-𑱬𑱲-𑲏𑴀-𑴆𑴈-𑴉𑴋-𑴰𑵆𑵐-𑵙𑵠-𑵥𑵧-𑵨𑵪-𑶉𑶘𑶠-𑶩𑻠-𑻲𑼂𑼄-𑼐𑼒-𑼳𑽐-𑽙𑾰𑿀-𑿔𒀀-𒎙𒐀-𒑮𒒀-𒕃𒾐-𒿰𓀀-𓐯𓑁-𓑆𓑠-𔏺𔐀-𔙆𖄀-𖄝𖄰-𖄹𖠀-𖨸𖩀-𖩞𖩠-𖩩𖩰-𖪾𖫀-𖫉𖫐-𖫭𖬀-𖬯𖭀-𖭃𖭐-𖭙𖭛-𖭡𖭣-𖭷𖭽-𖮏𖵀-𖵬𖵰-𖵹𖹀-𖺖𖼀-𖽊𖽐𖾓-𖾟𖿠-𖿡𖿣𗀀-𘟷𘠀-𘳕𘳿-𘴈𚿰-𚿳𚿵-𚿻𚿽-𚿾𛀀-𛄢𛄲𛅐-𛅒𛅕𛅤-𛅧𛅰-𛋻𛰀-𛱪𛱰-𛱼𛲀-𛲈𛲐-𛲙𜳰-𜳹𝋀-𝋓𝋠-𝋳𝍠-𝍸𝐀-𝑔𝑖-𝒜𝒞-𝒟𝒢𝒥-𝒦𝒩-𝒬𝒮-𝒹𝒻𝒽-𝓃𝓅-𝔅𝔇-𝔊𝔍-𝔔𝔖-𝔜𝔞-𝔹𝔻-𝔾𝕀-𝕄𝕆𝕊-𝕐𝕒-𝚥𝚨-𝛀𝛂-𝛚𝛜-𝛺𝛼-𝜔𝜖-𝜴𝜶-𝝎𝝐-𝝮𝝰-𝞈𝞊-𝞨𝞪-𝟂𝟄-𝟋𝟎-𝟿𝼀-𝼞𝼥-𝼪𞀰-𞁭𞄀-𞄬𞄷-𞄽𞅀-𞅉𞅎𞊐-𞊭𞋀-𞋫𞋰-𞋹𞓐-𞓫𞓰-𞓹𞗐-𞗭𞗰-𞗺𞟠-𞟦𞟨-𞟫𞟭-𞟮𞟰-𞟾𞠀-𞣄𞣇-𞣏𞤀-𞥃𞥋𞥐-𞥙𞱱-𞲫