$$;

create or replace function public.traffic_editor_catalog_id(p_catalog text)
returns bigint language sql stable security invoker set search_path=pg_catalog,public as $$
 select s.sclad_id from public.sclad s
 where public.traffic_editor_catalog_key(p_catalog) <> ''
   and public.traffic_editor_catalog_key(s.part_number::text) = public.traffic_editor_catalog_key(p_catalog)
 order by s.sclad_id asc limit 1
$$;
grant execute on function public.traffic_editor_catalog_id(text) to anon,authenticated;

create or replace function public.traffic_editor_name_ids(p_query text)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 select coalesce(jsonb_agg(x.sclad_id order by x.sclad_id),'[]'::jsonb) from (
   select s.sclad_id from public.sclad s
   where length(btrim(coalesce(p_query,''))) >= 2
     and (strpos(lower(coalesce(s.name::text,'')),lower(btrim(p_query))) > 0
       or strpos(lower(coalesce(s.part_number::text,'')),lower(btrim(p_query))) > 0)
   order by s.sclad_id asc limit 50
 ) x
$$;
grant execute on function public.traffic_editor_name_ids(text) to anon,authenticated;


-- SOURCE: 20261009010000_traffic_editor_search.sql
-- Editor stock search: same matching rules, stable ID pages, existing permissions.
create or replace function public.traffic_editor_stock_search(p_query text,p_by_name boolean default false,p_after bigint default null)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 with q as (select lower(btrim(coalesce(p_query,''))) raw, public.traffic_editor_catalog_key(p_query) normalized),
 matches as (
 select s.sclad_id from public.sclad s cross join q
 where q.raw <> '' and (p_after is null or s.sclad_id > p_after)
 and case when p_by_name then
   not exists (select 1 from unnest(regexp_split_to_array(q.raw,'\s+')) token where strpos(lower(coalesce(s.name::text,'')),token)=0)
 else strpos(lower(coalesce(s.part_number::text,'')),q.raw)>0
   or strpos(lower(coalesce(s.name::text,'')),q.raw)>0
   or (q.normalized <> '' and (strpos(public.traffic_editor_catalog_key(s.part_number::text),q.normalized)>0
     or strpos(public.traffic_editor_catalog_key(s.name::text),q.normalized)>0)) end
 order by s.sclad_id asc limit 51
 ), page as (select sclad_id from matches order by sclad_id limit 50)
 select jsonb_build_object('ids',coalesce((select jsonb_agg(sclad_id order by sclad_id) from page),'[]'::jsonb),
 'has_more',(select count(*)>50 from matches),'next_cursor',(select max(sclad_id) from page))
$$;
grant execute on function public.traffic_editor_stock_search(text,boolean,bigint) to anon,authenticated;


-- SOURCE: 20261009020000_traffic_analytics_staff.sql
-- Read-only analytic salary operands. Original values/types/order and date keys retained.
create or replace function public.traffic_analytics_staff_data(p_data jsonb)
returns jsonb language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare result jsonb; history jsonb := '{}'::jsonb; day record; entry jsonb; entries jsonb; records jsonb;
begin
 if jsonb_typeof(p_data) is distinct from 'object' then return '{}'::jsonb; end if;
 result := jsonb_build_object('Name',p_data->'Name','Доступ',p_data->'Доступ');
 if jsonb_typeof(p_data->'Історія') is distinct from 'object' then
   return result || jsonb_build_object('Історія',p_data->'Історія');
 end if;
 for day in select * from jsonb_each(p_data->'Історія') loop
   if jsonb_typeof(day.value) <> 'array' then history := history || jsonb_build_object(day.key,day.value); continue; end if;
   entries := '[]'::jsonb;
   for entry in select value from jsonb_array_elements(day.value) loop
     if jsonb_typeof(entry) <> 'object' then entries := entries || jsonb_build_array(entry); continue; end if;
     records := entry->'Записи';
     if jsonb_typeof(records) = 'array' then
       select coalesce(jsonb_agg(case when jsonb_typeof(value)='object' then
         jsonb_build_object('Зарплата',value->'Зарплата') else value end order by ordinality),'[]'::jsonb)
         into records from jsonb_array_elements(records) with ordinality;
     end if;
     entries := entries || jsonb_build_array(jsonb_build_object('СуммаРоботи',entry->'СуммаРоботи','Записи',records));
   end loop;
   history := history || jsonb_build_object(day.key,entries);
 end loop;
 return result || jsonb_build_object('Історія',history);
end $$;
create or replace function public.traffic_analytics_staff(p_after bigint default null)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 with candidates as (select s.slyusar_id,s.data from public.slyusars s
   where p_after is null or s.slyusar_id>p_after order by s.slyusar_id limit 201),
 page as (select slyusar_id,public.traffic_analytics_staff_data(to_jsonb(data)) data
   from candidates order by slyusar_id limit 200)
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(p) order by slyusar_id) from page p),'[]'::jsonb),
 'has_more',(select count(*)>200 from candidates),'next_cursor',(select max(slyusar_id) from page))
$$;
grant execute on function public.traffic_analytics_staff(bigint) to anon,authenticated;


-- SOURCE: 20261009030000_traffic_client_values.sql
-- Unique scalar editing suggestions; concrete car/client selections retain distinct IDs.

create or replace function public.traffic_client_form_options(
  p_kind text, p_query text default '', p_after bigint default null,
  p_client bigint default null
) returns jsonb language plpgsql stable security invoker
set search_path = pg_catalog, public
as $$
declare result jsonb; field_name text;
begin
  if p_kind in ('client','phone') then
    field_name := case when p_kind='client' then 'ПІБ' else 'Телефон' end;
    with candidates as (
      select client_id as id, public.sto_read_object_v1(data::jsonb) as d
      from public.clients
      where (p_after is null or client_id > p_after)
        and (p_client is null or client_id=p_client)
    ), page as (
      select * from candidates where coalesce(d->>'ПІБ','') <> ''
        and (strpos(lower(coalesce(d->>field_name,'')),lower(coalesce(p_query,'')))>0
          or (p_kind='phone' and regexp_replace(coalesce(p_query,''),'[^0-9]','','g')<>''
            and strpos(regexp_replace(coalesce(d->>field_name,''),'[^0-9]','','g'),
              regexp_replace(p_query,'[^0-9]','','g'))>0))
      order by id limit 21
    ), visible as (select * from page order by id limit 20)
    select jsonb_build_object('items', coalesce((select jsonb_agg(jsonb_build_object(
      'id',id::text,'fullName',coalesce(d->>'ПІБ',''),'phone',coalesce(d->>'Телефон',''),
      'data',jsonb_build_object('ПІБ',d->'ПІБ','Телефон',d->'Телефон')) order by id) from visible),'[]'::jsonb),
      'has_more',(select count(*)>20 from page),'next_cursor',(select max(id) from visible)) into result;
  else
    field_name := case p_kind when 'carModel' then 'Авто' when 'carNumber' then 'Номер авто'
      when 'carCodeEdit' then 'КодДВЗ' when 'carEngineEdit' then 'Обʼєм'
      when 'carVinEdit' then 'Vincode' when 'carModelEdit' then 'Авто'
      when 'carNumberEdit' then 'Номер авто' else null end;
    if field_name is null then raise exception 'Unsupported form field'; end if;
    with candidates as (
      select cars_id as id, client_id, public.sto_read_object_v1(data::jsonb) as d
      from public.cars where is_deleted is not true
        and (p_client is null or client_id=p_client)
    ), unique_candidates as (
      select distinct on (case when right(p_kind,4)='Edit' then d->>field_name else id::text end) *
      from candidates
      order by (case when right(p_kind,4)='Edit' then d->>field_name else id::text end), id
    ), page as (
      select * from unique_candidates where (p_after is null or id>p_after) and coalesce(d->>field_name,'') <> ''
        and strpos(lower(coalesce(d->>field_name,'')),lower(coalesce(p_query,'')))>0
      order by id limit 21
    ), visible as (select * from page order by id limit 20)
    select jsonb_build_object('items',coalesce((select jsonb_agg(
      jsonb_build_object('id',id::text,'client_id',client_id::text,'label',d->>field_name,
        'Авто',d->'Авто','Номер авто',d->'Номер авто') order by id) from visible),'[]'::jsonb),
      'has_more',(select count(*)>20 from page),'next_cursor',(select max(id) from visible)) into result;
  end if;
  return result;
end;
$$;
revoke all on function public.traffic_client_form_options(text,text,bigint,bigint) from public;
grant execute on function public.traffic_client_form_options(text,text,bigint,bigint) to anon, authenticated;


-- SOURCE: 20261010010000_traffic_receipter_salaries.sql
-- Compact salary operands only for acts already selected by the profit report.
create or replace function public.traffic_receipter_salaries(p_ids bigint[])
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb;
begin
 if coalesce(cardinality(p_ids),0)>200 then raise exception 'At most 200 act IDs'; end if;
 if coalesce(cardinality(p_ids),0)=0 then return '[]'::jsonb; end if;
 with staff as (select slyusar_id,public.sto_read_object_v1(to_jsonb(data)) d from public.slyusars),
 entries as (
 select s.slyusar_id,day.key,entry.ordinality,entry.value r
 from staff s cross join lateral jsonb_each(case when jsonb_typeof(s.d->'Історія')='object' then s.d->'Історія' else '{}'::jsonb end) day
 cross join lateral jsonb_array_elements(case when jsonb_typeof(day.value)='array' then day.value else '[]'::jsonb end) with ordinality entry
 where s.d->>'Доступ'='Приймальник'
 )
 select coalesce(jsonb_agg(jsonb_build_object('Акт',r->'Акт','ЗарплатаЗапчастин',r->'ЗарплатаЗапчастин',
 'ЗарплатаРоботи',r->'ЗарплатаРоботи','ЗарплатаЗапчастистів',r->'ЗарплатаЗапчастистів') order by slyusar_id,key,ordinality),'[]'::jsonb)
 into result from entries where
 case when length(coalesce(r->>'Акт',''))<40 and r->>'Акт' ~ '^\s*[+]?[0-9]+(\.0+)?\s*$'
 then (r->>'Акт')::numeric=any(p_ids::numeric[]) else true end;
 -- Unusual legacy ID strings remain for exact JavaScript Number matching by caller.
 return result;
end $$;
grant execute on function public.traffic_receipter_salaries(bigint[]) to anon,authenticated;


-- SOURCE: 20261011010000_traffic_profit_acts.sql
-- Profit report operands only. No financial writes or new tables.
create or replace function public.traffic_profit_acts(
 p_mode text, p_from text, p_to text default null, p_offset integer default 0
) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb;
begin
 if p_mode not in ('open','close','paid') or p_mode is null then raise exception 'Invalid date mode'; end if;
 if p_offset is null or p_offset<0 then raise exception 'Invalid offset'; end if;
 with candidates as (
   select a.act_id,a.date_on,to_jsonb(a) row_data,public.sto_read_object_v1(to_jsonb(a.data)) body
   from public.acts a
   where case p_mode
     when 'open' then (p_from is null or a.date_on>=p_from::timestamptz) and (p_to is null or a.date_on<=p_to::timestamptz)
     when 'close' then (p_from is null or a.date_off>=p_from::timestamptz) and (p_to is null or a.date_off<=p_to::timestamptz)
     -- This existing column is text: preserve the report's existing PostgREST comparison.
     when 'paid' then (p_from is null or a.rosraxovano>=p_from) and (p_to is null or a.rosraxovano<=p_to)
   end
   order by a.date_on desc,a.act_id desc limit 201 offset p_offset
 ), page as (select * from candidates order by date_on desc,act_id desc limit 200)
 select jsonb_build_object('items',coalesce((select jsonb_agg(
   (select jsonb_object_agg(key,value) from jsonb_each(p.row_data)
    where key=any(array['act_id','date_on','date_off','rosraxovano','xto_rozraxuvav','client_id','cars_id','avans','tupOplatu']))
   ||jsonb_build_object('data',(select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(p.body)
    where key=any(array['Прибуток за деталі','Прибуток за роботу','За деталі','За роботу','Знижка','Заморожений'])))
   order by p.date_on desc,p.act_id desc) from page p),'[]'::jsonb),
   'has_more',(select count(*)>200 from candidates)) into result;
 return result;
end $$;
revoke all on function public.traffic_profit_acts(text,text,text,integer) from public;
grant execute on function public.traffic_profit_acts(text,text,text,integer) to anon,authenticated;


-- SOURCE: 20261011020000_traffic_shop_report.sql
-- Details-by-act report needs history and name, never shop stock/configuration.
create or replace function public.traffic_shop_report(p_after bigint default null)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 with candidates as (
  select shop_id,public.sto_read_object_v1(to_jsonb(data)) body from public.shops
  where p_after is null or shop_id>p_after order by shop_id limit 201
 ), page as (select * from candidates order by shop_id limit 200)
 select jsonb_build_object('items',coalesce((select jsonb_agg(jsonb_build_object(
  'shop_id',shop_id,'data',(select coalesce(jsonb_object_agg(key,value),'{}'::jsonb)
   from jsonb_each(body) where key in ('Name','Історія'))) order by shop_id) from page),'[]'::jsonb),
  'has_more',(select count(*)>200 from candidates),'next_cursor',(select max(shop_id) from page));
$$;
revoke all on function public.traffic_shop_report(bigint) from public;
grant execute on function public.traffic_shop_report(bigint) to anon,authenticated;


-- SOURCE: 20261011030000_traffic_batch_suggestions.sql
-- Bounded stock-form lookups. No new tables; all reads obey caller RLS.
create or replace function public.traffic_batch_suggestions(p_kind text,p_query text default '',p_offset integer default 0,p_exact boolean default false)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare rows jsonb; q text := lower(btrim(coalesce(p_query,'')));
begin
 if p_kind in ('shops','details') then
  with names as (
   select public.traffic_reference_name(to_jsonb(s.data)) as name from public.shops s where p_kind='shops'
   union all select public.traffic_reference_name(to_jsonb(d.data)) from public.details d where p_kind='details'
  ) select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into rows from (
   select distinct name as value from names where name is not null and
   (case when p_exact then lower(btrim(name))=q else strpos(lower(name),q)>0 end)
   order by value offset greatest(p_offset,0) limit 21
  ) x;
 elsif p_kind='catalogs' then
  select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into rows from (
   select distinct btrim(s.part_number::text) as value,btrim(s.name::text) as name
   from public.sclad s where nullif(btrim(s.part_number::text),'') is not null and
   (case when p_exact then btrim(s.part_number::text)=btrim(p_query)
    else q='' or strpos(lower(s.part_number),q)>0 or (public.traffic_catalog_key(p_query)<>'' and strpos(public.traffic_catalog_key(s.part_number),public.traffic_catalog_key(p_query))>0) end)
   order by value,name offset greatest(p_offset,0) limit 21
  ) x;
 elsif p_kind='acts' then
  select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into rows from (
   select a.act_id::text as value,a.date_off, concat_ws(' · ',a.act_id::text,public.sto_read_object_v1(c.data::jsonb)->>'ПІБ',public.sto_read_object_v1(v.data::jsonb)->>'Авто',public.sto_read_object_v1(v.data::jsonb)->>'Номер авто') as label from public.acts a
   left join public.clients c on c.client_id=a.client_id
   left join public.cars v on v.cars_id=a.cars_id
   where a.date_off is null and
   (case when p_exact then a.act_id::text=btrim(p_query) else strpos(lower(concat_ws(' ',a.act_id::text,public.sto_read_object_v1(c.data::jsonb)->>'ПІБ',public.sto_read_object_v1(v.data::jsonb)->>'Авто',public.sto_read_object_v1(v.data::jsonb)->>'Номер авто')),q)>0 end)
   order by a.act_id desc offset greatest(p_offset,0) limit 21
  ) x;
 else raise exception 'Unsupported batch lookup'; end if;
 return jsonb_build_object('items',(select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb)
  from jsonb_array_elements(rows) with ordinality where ordinality<=20),'has_more',jsonb_array_length(rows)>20);
end $$;
revoke all on function public.traffic_batch_suggestions(text,text,integer,boolean) from public;
grant execute on function public.traffic_batch_suggestions(text,text,integer,boolean) to anon,authenticated;

-- One bounded OCR mapping request for up to 100 unique catalog numbers.
create or replace function public.traffic_invoice_catalogs(p_catalogs text[],p_offset integer default 0)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare rows jsonb;
begin
 if coalesce(cardinality(p_catalogs),0)>100 then raise exception 'Expected at most 100 catalogs';end if;
 select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into rows from (
  select btrim(s.part_number::text) as catalog,btrim(s.name::text) as name,min(s.sclad_id) as id
  from public.sclad s where btrim(s.part_number::text)=any(p_catalogs) and nullif(btrim(s.name::text),'') is not null
  group by btrim(s.part_number::text),btrim(s.name::text) order by catalog,name
  offset greatest(coalesce(p_offset,0),0) limit 201
 ) x;
 return jsonb_build_object('items',(select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb)
  from jsonb_array_elements(rows) with ordinality where ordinality<=200),'has_more',jsonb_array_length(rows)>200);
end $$;
revoke all on function public.traffic_invoice_catalogs(text[],integer) from public;
grant execute on function public.traffic_invoice_catalogs(text[],integer) to anon,authenticated;

create or replace function public.traffic_stock_position(p_id bigint)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 select jsonb_build_object('sclad_id',s.sclad_id,'time_on',s.time_on,'shops',s.shops,'part_number',s.part_number,'name',s.name,
  'kilkist_on',s.kilkist_on,'price',s.price,'rahunok',s.rahunok,'unit_measurement',s.unit_measurement,'scladNomer',s."scladNomer",'xto_zamovuv',s.xto_zamovuv,
  'shop_id',public.traffic_reference_id('shops',s.shops),'detail_id',public.traffic_reference_id('details',s.name),
  'employee_name',(select public.traffic_reference_name(to_jsonb(e.data)) from public.slyusars e where e.slyusar_id=s.xto_zamovuv))
 from public.sclad s where s.sclad_id=p_id
$$;
revoke all on function public.traffic_stock_position(bigint) from public;
