-- SOURCE: 20261011040000_traffic_act_search.sql
-- Read-only smart-search helpers. They preserve JS truthiness and scalar conversion.

create or replace function public.traffic_search_truthy(v jsonb) returns boolean
language sql immutable security invoker set search_path=pg_catalog as $$
 select coalesce(v not in ('null'::jsonb,'false'::jsonb,'0'::jsonb,'""'::jsonb),false);
$$;
create or replace function public.traffic_search_string(v jsonb) returns text
language plpgsql immutable security invoker set search_path=pg_catalog,public as $$
declare result text;
begin
 if v is null then return 'undefined'; end if;
 if jsonb_typeof(v)='string' then return v#>>'{}'; end if;
 if jsonb_typeof(v)='object' then return '[object Object]'; end if;
 if jsonb_typeof(v)='array' then
   select coalesce(string_agg(case when x='null'::jsonb then '' else public.traffic_search_string(x) end,',' order by ord),'')
     into result from jsonb_array_elements(v) with ordinality a(x,ord);
   return result;
 end if;
 return v::text;
end;
$$;
create or replace function public.traffic_search_number(v jsonb) returns double precision
language plpgsql immutable security invoker set search_path=pg_catalog,public as $$
declare t text; n double precision:=0; digit integer; radix integer; c text;
begin
 if v is null then return null; end if;
 if v='null'::jsonb or v='false'::jsonb then return 0; end if;
 if v='true'::jsonb then return 1; end if;
 t:=btrim(public.traffic_search_string(v), E' \t\r\n\v\f'||chr(160)||chr(65279));
 if t='' then return 0; end if;
 if t ~ '^0[xX][0-9a-fA-F]+$' or t ~ '^0[bB][01]+$' or t ~ '^0[oO][0-7]+$' then
   radix:=case lower(substr(t,2,1)) when 'x' then 16 when 'b' then 2 else 8 end;
   for i in 3..length(t) loop digit:=strpos('0123456789abcdef',lower(substr(t,i,1)))-1;n:=n*radix+digit;end loop;
   return n;
 end if;
 if t in ('Infinity','+Infinity','-Infinity') then return t::double precision; end if;
 if t !~ '^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]+)?$' then return null; end if;
 return t::double precision;
 exception when invalid_text_representation then return null;
 when numeric_value_out_of_range then
   begin if abs(t::numeric)<1 then return 0;end if;
   exception when numeric_value_out_of_range then if t ~ '[eE]-' then return 0;end if;end;
   return case when left(t,1)='-' then '-Infinity'::double precision else 'Infinity'::double precision end;
end;
$$;
create or replace function public.traffic_search_trim(v text) returns text
language sql immutable security invoker set search_path=pg_catalog as $$
 select regexp_replace(v,U&'^[[:space:]\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]+|[[:space:]\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]+$','','g');
$$;
create or replace function public.traffic_search_strip_space(v text) returns text
language sql immutable security invoker set search_path=pg_catalog as $$
 select regexp_replace(v,U&'[[:space:]\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]','','g');
$$;
create or replace function public.traffic_search_text(d jsonb,keys text[]) returns text
language sql immutable security invoker set search_path=pg_catalog,public as $$
 select coalesce((select public.traffic_search_trim(public.traffic_search_string(d->k)) from unnest(keys) with ordinality a(k,ord)
 where d->k is not null and d->k<>'null'::jsonb and public.traffic_search_trim(public.traffic_search_string(d->k))<>'' order by ord limit 1),'');
$$;
create or replace function public.traffic_act_search_match(a jsonb,client_data jsonb,car_data jsonb,filters jsonb)
returns boolean language plpgsql immutable security invoker set search_path=pg_catalog,public as $$
declare d jsonb; cl jsonb; car jsonb; raw jsonb; f jsonb; val text; typ text; low text;
 pib text; phone text; carname text; plate text; works jsonb; parts jsonb; amount double precision; target double precision;
 hit boolean; code text; at_date timestamptz; formatted_date text; amount_text text;
begin
 if coalesce(jsonb_array_length(filters),0)=0 then return true;end if;
 d:=public.sto_read_object_v1(case when public.traffic_search_truthy(a->'info') then a->'info'
   when public.traffic_search_truthy(a->'data') then a->'data' else a->'details' end);
 cl:=public.sto_read_object_v1(client_data);car:=public.sto_read_object_v1(car_data);
 pib:=case when public.traffic_search_truthy(cl->'ПІБ') then public.traffic_search_string(cl->'ПІБ') else 'Невідомо' end;
 phone:=translate(public.traffic_search_strip_space(case when public.traffic_search_truthy(cl->'Телефон') then public.traffic_search_string(cl->'Телефон') else '' end),'()-','');
 plate:=coalesce(nullif(public.traffic_search_text(car,array['Номер авто','Держ. номер','plate','number']),''),public.traffic_search_text(d,array['Номер авто','Держ. номер']));
 carname:=public.traffic_search_text(car,array['Авто','Автомобіль','auto','car','name']);
 if carname='' then carname:=btrim(public.traffic_search_text(car,array['Марка','brand','make'])||' '||public.traffic_search_text(car,array['Модель','model'])); end if;
 if carname='' then carname:=public.traffic_search_text(d,array['Автомобіль','Авто','Марка']);end if;
 works:=case when jsonb_typeof(d->'Роботи')='array' then d->'Роботи' else '[]'::jsonb end;
 parts:=case when jsonb_typeof(d->'Деталі')='array' then d->'Деталі' else '[]'::jsonb end;
 raw:=coalesce((select x from unnest(array[d->'Загальна сума',d->'total',d->'amount',a->'total',a->'amount']) with ordinality t(x,ord) where public.traffic_search_truthy(x) order by ord limit 1),a->'amount');
 amount:=coalesce(public.traffic_search_number(raw),0);
 for f in select value from jsonb_array_elements(coalesce(filters,'[]'::jsonb)) loop
   typ:=f->>'type';val:=coalesce(f->>'value','');low:=lower(val);hit:=false;
   case typ
   when 'act' then hit:=strpos(coalesce(a->>'act_id',''),val)>0;
   when 'pib' then hit:=strpos(lower(pib),low)>0;
   when 'phone' then hit:=strpos(phone,val)>0;
   when 'car' then hit:=strpos(lower(carname),low)>0;
   when 'carNumber' then hit:=strpos(upper(public.traffic_search_strip_space(plate)),upper(val))>0;
   when 'date' then
     begin at_date:=(a->>'date_on')::timestamptz;hit:=at_date>=(f->>'dateFrom')::timestamptz and at_date<=(f->>'dateTo')::timestamptz;
     exception when invalid_datetime_format or datetime_field_overflow then hit:=false;end;
   when 'amount' then
     target:=public.traffic_search_number(f->'amountVal');
     hit:=case f->>'amountOp' when '>=' then amount>=target when '<=' then amount<=target when '>' then amount>target when '<' then amount<target when '=' then amount=target else false end;
   when 'status' then
     hit:=case val when 'open' then not public.traffic_search_truthy(a->'date_off') when 'closed' then public.traffic_search_truthy(a->'date_off')
       when 'paid' then public.traffic_search_truthy(a->'rosraxovano') when 'unpaid' then not public.traffic_search_truthy(a->'rosraxovano')
       when 'withAdvance' then public.traffic_search_number(a->'avans')>0
       when 'withDiscount' then public.traffic_search_number(d->'Знижка')>0 else true end;
   when 'raxunok' then hit:=strpos(case when public.traffic_search_truthy(a->'contrAgent_raxunok') then public.traffic_search_string(a->'contrAgent_raxunok') else '' end,val)>0;
   when 'actDoc' then hit:=strpos(case when public.traffic_search_truthy(a->'contrAgent_act') then public.traffic_search_string(a->'contrAgent_act') else '' end,val)>0;
   when 'pruimalnyk' then hit:=strpos(lower(coalesce(a->>'pruimalnyk','')),low)>0;
   when 'work','detail','slusar' then
     select exists(select 1 from jsonb_array_elements(case when typ='detail' then parts else works end) w
       where strpos(lower(case when typ='slusar' then coalesce(w->>'Слюсар','')
         else case when public.traffic_search_truthy(w->case when typ='work' then 'Робота' else 'Деталь' end)
           then w->>case when typ='work' then 'Робота' else 'Деталь' end else coalesce(w->>'Назва','') end end),low)>0) into hit;
   when 'text' then
     hit:=strpos(lower(pib),low)>0 or strpos(phone,val)>0 or strpos(lower(plate),low)>0 or strpos(lower(carname),low)>0 or strpos(coalesce(a->>'act_id',''),val)>0
       or strpos(lower(coalesce(a->>'pruimalnyk','')),low)>0 or strpos(lower(coalesce(d->>'Рекомендації','')),low)>0
       or strpos(lower(coalesce(d->>'Причина звернення','')),low)>0 or strpos(lower(coalesce(d->>'Примітки','')),low)>0
       or strpos(case when public.traffic_search_truthy(a->'contrAgent_raxunok') then public.traffic_search_string(a->'contrAgent_raxunok') else '' end,val)>0
       or strpos(case when public.traffic_search_truthy(a->'contrAgent_act') then public.traffic_search_string(a->'contrAgent_act') else '' end,val)>0;
     if not hit then select exists(select 1 from jsonb_array_elements(works) w where strpos(lower(case when public.traffic_search_truthy(w->'Робота') then w->>'Робота' else coalesce(w->>'Назва','') end),low)>0 or strpos(lower(coalesce(w->>'Слюсар','')),low)>0)
       or exists(select 1 from jsonb_array_elements(parts) w where strpos(lower(case when public.traffic_search_truthy(w->'Деталь') then w->>'Деталь' else coalesce(w->>'Назва','') end),low)>0) into hit;end if;
   when 'legacy' then
     code:=lower(coalesce(f->>'key',''));formatted_date:='';
     if a->>'date_on' is not null then formatted_date:=to_char((a->>'date_on')::timestamptz at time zone coalesce(f->>'timezone','UTC'),'DD.MM.YY');end if;
     amount_text:=amount::text;
     if abs(amount)>=0.000001 and abs(amount)<1e21 and amount_text ~ '[eE]' then amount_text:=(amount_text::numeric)::text;end if;
     amount_text:=regexp_replace(amount_text,'e([+-])0+','e\1');
     if upper(val) like 'СФ-%' or upper(val) like 'ОУ-%' then
       raw:=a->case when upper(val) like 'СФ-%' then 'contrAgent_raxunok' else 'contrAgent_act' end;
       val:=btrim(substr(upper(val),4));
       hit:=case when val='' then public.traffic_search_truthy(raw) else strpos(case when public.traffic_search_truthy(raw) then public.traffic_search_string(raw) else '' end,val)>0 end;
     else
       case code
       when 'акт' then hit:=strpos(coalesce(a->>'act_id',''),val)>0;
       when 'сума' then
         target:=public.traffic_search_number(to_jsonb(substring(btrim(val) from '^[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?')));
         hit:=amount>=target;
       when 'дата' then hit:=strpos(formatted_date,val)>0;
       when 'тел','телефон' then hit:=strpos(phone,val)>0;
       when 'піб' then hit:=strpos(lower(pib),low)>0;
       when 'машина' then hit:=strpos(lower(carname),low)>0;
       when 'номер' then hit:=strpos(plate,val)>0;
       else
         hit:=strpos(lower(pib),low)>0 or strpos(phone,val)>0 or strpos(plate,val)>0 or strpos(lower(carname),low)>0
           or strpos(coalesce(a->>'act_id',''),val)>0 or strpos(formatted_date,val)>0 or strpos(amount_text,val)>0
           or strpos(case when public.traffic_search_truthy(a->'contrAgent_raxunok') then public.traffic_search_string(a->'contrAgent_raxunok') else '' end,val)>0
           or strpos(case when public.traffic_search_truthy(a->'contrAgent_act') then public.traffic_search_string(a->'contrAgent_act') else '' end,val)>0
           or strpos(lower(coalesce(a->>'pruimalnyk','')),low)>0 or strpos(lower(coalesce(d->>'Рекомендації','')),low)>0
           or strpos(lower(coalesce(d->>'Причина звернення','')),low)>0 or strpos(lower(coalesce(d->>'Примітки','')),low)>0;
         if not hit then select exists(select 1 from jsonb_array_elements(works) w where strpos(lower(case when public.traffic_search_truthy(w->'Робота') then w->>'Робота' else coalesce(w->>'Назва','') end),low)>0 or strpos(lower(coalesce(w->>'Слюсар','')),low)>0)
           or exists(select 1 from jsonb_array_elements(parts) w where strpos(lower(case when public.traffic_search_truthy(w->'Деталь') then w->>'Деталь' else coalesce(w->>'Назва','') end),low)>0) into hit;end if;
       end case;
     end if;
   else raise exception 'Unsupported search filter: %',typ;
   end case;
   if not coalesce(hit,false) then return false;end if;
 end loop;
 return true;
end;
$$;
revoke all on function public.traffic_search_trim(text),public.traffic_search_strip_space(text),public.traffic_search_truthy(jsonb),public.traffic_search_string(jsonb),public.traffic_search_number(jsonb),public.traffic_search_text(jsonb,text[]),public.traffic_act_search_match(jsonb,jsonb,jsonb,jsonb) from public;
grant execute on function public.traffic_search_trim(text),public.traffic_search_strip_space(text),public.traffic_search_truthy(jsonb),public.traffic_search_string(jsonb),public.traffic_search_number(jsonb),public.traffic_search_text(jsonb,text[]),public.traffic_act_search_match(jsonb,jsonb,jsonb,jsonb) to anon,authenticated;

create or replace function public.traffic_act_search_page(
 p_from timestamptz default null,p_to timestamptz default null,p_mode text default null,
 p_filters jsonb default '[]',p_offset integer default 0,p_sort text default 'id'
) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
begin
 if p_offset<0 or p_offset is null or p_sort not in ('id','open','created','closed') or p_sort is null then raise exception 'Invalid search page';end if;
 if jsonb_typeof(p_filters)<>'array' or jsonb_array_length(p_filters)>50 then raise exception 'Invalid search filters';end if;
 if p_mode is not null and p_mode not in ('open','closed','frozen') then raise exception 'Invalid search mode';end if;
 return (with candidates as materialized (
  select a.act_id,a.date_on,a.date_off,to_jsonb(a) a,cl.client_id,cl.data::jsonb client_data,c.cars_id,c.data::jsonb car_data
  from public.acts a left join public.clients cl on cl.client_id=a.client_id left join public.cars c on c.cars_id=a.cars_id
  where case p_mode when 'open' then a.date_off is null when 'closed' then a.date_off is not null when 'frozen' then true
    else p_from is not null and p_to is not null and a.date_on>=p_from and a.date_on<=p_to end
   and case when p_mode='frozen' then public.sto_read_object_v1(a.data::jsonb)->'Заморожений'='true'::jsonb
     when p_mode in ('open','closed') then coalesce(public.sto_read_object_v1(a.data::jsonb)->'Заморожений'<>'true'::jsonb,true) else true end
 ), matched as materialized (
  select * from candidates where public.traffic_act_search_match(a,client_data,car_data,p_filters)
 ), page as (
  select * from matched order by
    case when p_sort='open' then (date_off is null)::integer end desc nulls last,
    case when p_sort='closed' then (date_off is not null)::integer end desc nulls last,
    case when p_sort='closed' then coalesce(date_off,date_on,'epoch'::timestamptz) when p_sort='created' then coalesce(date_on,'epoch'::timestamptz) end desc nulls last,
    act_id desc offset p_offset limit 50
 ) select jsonb_build_object(
 'items',coalesce((select jsonb_agg(
   (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(p.a) where key=any(array[
     'act_id','date_on','date_off','cars_id','client_id','pruimalnyk','slusarsOn','sms','avans','rosraxovano',
     'contrAgent_act','contrAgent_act_data','contrAgent_raxunok','contrAgent_raxunok_data','total','amount']))
   || jsonb_build_object('__sto_projection','act-search-v1','data',
     case when jsonb_typeof(public.sto_act_list_data_v1(p.a->'data'))='object' then public.sto_act_list_data_v1(p.a->'data')-'Роботи'-'Деталі' else p.a->'data' end)
   || case when p.a ? 'info' then jsonb_build_object('info',case when jsonb_typeof(public.sto_act_list_data_v1(p.a->'info'))='object' then public.sto_act_list_data_v1(p.a->'info')-'Роботи'-'Деталі' else p.a->'info' end) else '{}'::jsonb end
   || case when p.a ? 'details' then jsonb_build_object('details',case when jsonb_typeof(public.sto_act_list_data_v1(p.a->'details'))='object' then public.sto_act_list_data_v1(p.a->'details')-'Роботи'-'Деталі' else p.a->'details' end) else '{}'::jsonb end
 order by
    case when p_sort='open' then (p.date_off is null)::integer end desc nulls last,
    case when p_sort='closed' then (p.date_off is not null)::integer end desc nulls last,
    case when p_sort='closed' then coalesce(p.date_off,p.date_on,'epoch'::timestamptz) when p_sort='created' then coalesce(p.date_on,'epoch'::timestamptz) end desc nulls last,
    p.act_id desc
 ) from page p),'[]'::jsonb),
 'clients',coalesce((select jsonb_agg(distinct jsonb_build_object('client_id',client_id,'data',
   (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(public.sto_read_object_v1(client_data)) where key=any(array['ПІБ','Телефон'])))) from page where client_id is not null),'[]'::jsonb),
 'cars',coalesce((select jsonb_agg(distinct jsonb_build_object('cars_id',cars_id,'data',
   (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(public.sto_read_object_v1(car_data)) where key=any(array['Номер авто','Держ. номер','plate','number','Авто','Автомобіль','auto','car','name','Марка','brand','make','Модель','model'])))) from page where cars_id is not null),'[]'::jsonb),
 'total',(select count(*) from candidates),'matched',(select count(*) from matched),
 'has_more',p_offset+50<(select count(*) from matched),
 'next_offset',case when p_offset+50<(select count(*) from matched) then p_offset+50 else null end
 ));
end;
$$;
revoke all on function public.traffic_act_search_page(timestamptz,timestamptz,text,jsonb,integer,text) from public;
grant execute on function public.traffic_act_search_page(timestamptz,timestamptz,text,jsonb,integer,text) to anon,authenticated;

create or replace function public.traffic_act_notification_counts(p_ids bigint[],p_reception text default null)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
begin
 if cardinality(p_ids)>50 then raise exception 'At most 50 act IDs';end if;
 return coalesce((select jsonb_agg(jsonb_build_object('act_id',act_id,'count',n)) from (
   select act_id,count(*) n from public.act_changes_notifications
   where act_id=any(p_ids) and delit=false and (p_reception is null or pruimalnyk=p_reception) group by act_id
 ) counts),'[]'::jsonb);
end;
$$;
revoke all on function public.traffic_act_notification_counts(bigint[],text) from public;
grant execute on function public.traffic_act_notification_counts(bigint[],text) to anon,authenticated;


-- SOURCE: 20261011040000_traffic_planner_occupancy.sql
-- Read-only aggregation; preserves existing calendar grouping and Math.round per booking.
-- Overlap semantics deliberately unchanged: reservations' durations are additive.
create or replace function public.traffic_planner_occupancy(p_start timestamptz,p_end timestamptz,p_timezone text)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb;
begin
 if p_start is null or p_end is null or p_end<=p_start or p_end-p_start>interval '32 days' then
   raise exception 'Expected a calendar month interval';
 end if;
 if not exists(select 1 from pg_timezone_names where name=p_timezone) then raise exception 'Invalid timezone'; end if;
 select coalesce(jsonb_agg(to_jsonb(x) order by x.day,x.post),'[]'::jsonb) into result from (
   select to_char(n.data_on::timestamptz at time zone p_timezone,'YYYY-MM-DD') as day,
     n.name_post post,
     sum(floor(extract(epoch from (n.data_off::timestamptz-n.data_on::timestamptz))/60+0.5)) minutes
   from public.post_arxiv n
   where n.data_on>=p_start and n.data_on<p_end and n.name_post is not null and n.name_post<>0
   group by 1,2
 ) x;
 return result;
end $$;
grant execute on function public.traffic_planner_occupancy(timestamptz,timestamptz,text) to anon,authenticated;



-- SOURCE: 20261011050000_traffic_planner_bookings.sql
-- Compact visible bookings with only the labels actually used by day/week renderers.
create or replace function public.traffic_planner_bookings(p_start timestamptz,p_end timestamptz,p_staff bigint[] default null,p_offset integer default 0)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb;
begin
 if p_start is null or p_end is null or p_end<p_start or p_end-p_start>interval '8 days' then raise exception 'Expected visible planner range'; end if;
 if p_offset<0 or coalesce(cardinality(p_staff),0)>200 then raise exception 'Invalid planner page'; end if;
 with bookings as (
 select post_arxiv_id,slyusar_id,name_post,client_id,cars_id,status,data_on,data_off,komentar,act_id,xto_zapusav
 from public.post_arxiv where data_on>=p_start and data_on<=p_end and (p_staff is null or slyusar_id=any(p_staff))
 order by post_arxiv_id limit 201 offset p_offset
 ), page as (select * from bookings order by post_arxiv_id limit 200), projected as (
 select p.post_arxiv_id,to_jsonb(p)||jsonb_build_object('version',md5(to_jsonb(p)::text),
 'client_data',coalesce((select jsonb_object_agg(e.key,e.value) from jsonb_each(case when jsonb_typeof(to_jsonb(c.data))='object' then to_jsonb(c.data) else '{}'::jsonb end) e where e.key='ПІБ' or lower(e.key) like '%телефон%'),'{}'::jsonb),
 'car_data',case when jsonb_typeof(to_jsonb(v.data))='object' then jsonb_build_object('Авто',to_jsonb(v.data)->'Авто','Номер авто',to_jsonb(v.data)->'Номер авто') else '{}'::jsonb end) item
 from page p
 left join public.clients c on c.client_id=case when p.client_id::text ~ '^\s*[+]?[0-9]+(\.0+)?\s*$' then p.client_id::text::numeric else null end
 left join public.cars v on v.cars_id=case when p.cars_id::text ~ '^\s*[+]?[0-9]+(\.0+)?\s*$' then p.cars_id::text::numeric else null end and v.is_deleted is distinct from true
 )
 select jsonb_build_object('items',coalesce((select jsonb_agg(item order by post_arxiv_id) from projected),'[]'::jsonb),'has_more',(select count(*)>200 from bookings)) into result;
 return result;
end $$;
grant execute on function public.traffic_planner_bookings(timestamptz,timestamptz,bigint[],integer) to anon,authenticated;


-- SOURCE: 20261011060000_traffic_dashboard_totals.sql
-- Compact dashboard per-act totals. Existing v1 stays compatible with older frontends.
create or replace function public.traffic_dashboard_data_v2(p_data jsonb)
returns jsonb language plpgsql immutable security invoker set search_path=pg_catalog,public as $$
declare d jsonb:=public.sto_read_object_v1(p_data); result jsonb; rows jsonb; row_value jsonb;
  field text; amount double precision; quantity double precision; subtotal double precision; totals jsonb:='{}'; count_works integer:=0;
begin
 foreach field in array array['Роботи','Деталі'] loop
  rows:=case when jsonb_typeof(d->field)='array' then d->field else '[]'::jsonb end;
  if field='Роботи' then count_works:=jsonb_array_length(rows); end if;
  subtotal:=0;
  for row_value in select value from jsonb_array_elements(rows) loop
   if jsonb_typeof(row_value)<>'object' then return public.traffic_dashboard_data(p_data); end if;
   amount:=public.traffic_search_number(case when public.traffic_search_truthy(row_value->'Ціна') then row_value->'Ціна' else '0'::jsonb end);
   quantity:=public.traffic_search_number(case when public.traffic_search_truthy(row_value->'Кількість') then row_value->'Кількість' else '1'::jsonb end);
   if amount is null or quantity is null or amount::text in ('Infinity','-Infinity','NaN') or quantity::text in ('Infinity','-Infinity','NaN') then
    return public.traffic_dashboard_data(p_data);
   end if;
   subtotal:=subtotal+amount*quantity;
  end loop;
  totals:=totals||jsonb_build_object(case field when 'Роботи' then 'works' else 'details' end,subtotal);
 end loop;
 select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) into result from jsonb_each(d)
 where key in ('ПІБ','Клієнт','Марка','Модель','Приймальник','Прибуток за роботу','Прибуток за деталі');
 return result||jsonb_build_object('__dashboard_totals',totals||jsonb_build_object('worksCount',count_works));
 exception when numeric_value_out_of_range then return public.traffic_dashboard_data(p_data);
end $$;
create or replace function public.traffic_dashboard_page_v2(p_from timestamptz,p_to timestamptz,p_before bigint default null)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 with page as (
   select a.act_id,a.date_on,a.date_off,a.client_id,a.cars_id,
     public.traffic_dashboard_data_v2(a.data::jsonb) data,
     jsonb_build_object('ПІБ',public.sto_read_object_v1(cl.data::jsonb)->'ПІБ',
       'Клієнт',public.sto_read_object_v1(cl.data::jsonb)->'Клієнт') __client_data,
     jsonb_build_object('Авто',public.sto_read_object_v1(c.data::jsonb)->'Авто',
       'Марка',public.sto_read_object_v1(c.data::jsonb)->'Марка',
       'Модель',public.sto_read_object_v1(c.data::jsonb)->'Модель') __car_data
   from public.acts a left join public.clients cl on cl.client_id=a.client_id
   left join public.cars c on c.cars_id=a.cars_id and c.is_deleted is not true
   where ((a.date_on>=p_from and a.date_on<p_to) or (a.date_off>=p_from and a.date_off<p_to))
     and (p_before is null or a.act_id<p_before)
   order by a.act_id desc limit 101
 ), visible as (select * from page order by act_id desc limit 100)
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(v) order by act_id desc) from visible v),'[]'::jsonb),
   'has_more',(select count(*)>100 from page),'next_cursor',(select min(act_id) from visible));
$$;
revoke all on function public.traffic_dashboard_data_v2(jsonb),public.traffic_dashboard_page_v2(timestamptz,timestamptz,bigint) from public;
grant execute on function public.traffic_dashboard_data_v2(jsonb),public.traffic_dashboard_page_v2(timestamptz,timestamptz,bigint) to anon,authenticated;


-- SOURCE: 20261011080000_traffic_payroll_json.sql
-- Pure strict JSON parser shared by payroll read and write contracts. No mutations.
create or replace function public.payroll_json_object(p_value jsonb)
returns jsonb language plpgsql immutable security invoker set search_path=pg_catalog as $$
begin
 if jsonb_typeof(p_value)='string' then p_value:=(p_value#>>'{}')::jsonb;end if;
 if jsonb_typeof(p_value) is distinct from 'object' then raise exception 'Некоректні дані зарплати' using errcode='40001';end if;
 return p_value;
end $$;


revoke all on function public.payroll_json_object(jsonb) from public;
grant execute on function public.payroll_json_object(jsonb) to anon,authenticated;


-- SOURCE: 20261011090000_traffic_attention_overview.sql
-- JavaScript display conversion used only by the existing attention rules.
create or replace function public.traffic_attention_text(v jsonb) returns text language plpgsql immutable as $$
declare result text;
begin
 if v is null or v='null'::jsonb then return ''; end if;
 if jsonb_typeof(v)='object' then return '[object Object]'; end if;
 if jsonb_typeof(v)='array' then
   select coalesce(string_agg(public.traffic_attention_text(value),',' order by ordinality),'') into result from jsonb_array_elements(v) with ordinality;
   return result;
 end if;
 return v#>>'{}';
end $$;
create or replace function public.traffic_attention_positive_price(v jsonb) returns boolean language plpgsql immutable as $$
declare s text; n double precision; digits text; base integer; total numeric:=0; digit integer; ch text;
begin
 s:=regexp_replace(public.traffic_attention_text(v),'[[:space:]'||chr(160)||chr(65279)||']','','g');
 s:=regexp_replace(s,',','.');
 if s ~ '^0[xX][0-9a-fA-F]+$' or s ~ '^0[bB][01]+$' or s ~ '^0[oO][0-7]+$' then
   base:=case lower(substr(s,2,1)) when 'x' then 16 when 'b' then 2 else 8 end;
   digits:=lower(substr(s,3));
   for i in 1..length(digits) loop ch:=substr(digits,i,1);digit:=strpos('0123456789abcdef',ch)-1;total:=total*base+digit;end loop;
   n:=total::double precision;
 elsif s ~ '^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]+)?$' then n:=s::double precision;
 else return false; end if;
 return n>0 and n<'Infinity'::double precision;
exception when others then return false;
end $$;

create or replace function public.traffic_attention_act_rules(a jsonb,p_role text,p_name text,p_prices boolean)
returns jsonb language plpgsql immutable as $$
declare d jsonb;works jsonb;details jsonb;section jsonb;rows jsonb;entry jsonb;items jsonb:='[]';keys text[];id text;amount integer;permitted boolean:=false;
begin
 if p_role='Приймальник' and a->>'pruimalnyk' is distinct from p_name then return jsonb_build_object('permitted',false,'items',items);end if;
 permitted:=p_role in ('Адміністратор','Приймальник','Запчастист','Складовщик');
 d:=a->'data';if jsonb_typeof(d)='string' then d:=(d#>>'{}')::jsonb;end if;
 if d is null or d='null'::jsonb then d:='{}';end if;
 if jsonb_typeof(d)<>'object' then raise exception 'Invalid act';end if;
 works:=case when jsonb_typeof(d->'Роботи')='array' then d->'Роботи' else '[]'::jsonb end;
 if p_role='Слюсар' then
   for entry in select value from jsonb_array_elements(works) loop
     if entry='null'::jsonb then raise exception 'Invalid work';end if;
     if entry->'Слюсар'=to_jsonb(p_name) then permitted:=true;exit;end if;
   end loop;
 else permitted:=p_role in ('Адміністратор','Приймальник','Запчастист','Складовщик');end if;
 if not permitted then return jsonb_build_object('permitted',false,'items',items);end if;
 select coalesce(jsonb_agg(w),'[]') into works from jsonb_array_elements(works) w
 where w->'Робота' not in ('null'::jsonb,'false'::jsonb,'0'::jsonb) and regexp_replace(public.traffic_attention_text(w->'Робота'),'^[[:space:]'||chr(160)||chr(65279)||']+|[[:space:]'||chr(160)||chr(65279)||']+$','','g')<>'';
 if p_role='Слюсар' and not exists(select 1 from jsonb_array_elements(works) w where w->'Слюсар'=to_jsonb(p_name)) then return jsonb_build_object('permitted',true,'items',items);end if;
 if d->'Заморожений'='true'::jsonb then return jsonb_build_object('permitted',true,'items',items);end if;
 section:=d->'__workshop_v1';
 if section is not null and section<>'null'::jsonb then
   if section->'version' is distinct from '1'::jsonb or jsonb_typeof(section->'defects') is distinct from 'array' or jsonb_typeof(section->'recommendations') is distinct from 'array' then raise exception 'Invalid workshop';end if;
   foreach id in array array['defects','recommendations'] loop
     keys:=array[]::text[];
     for entry in select value from jsonb_array_elements(section->id) loop
       if jsonb_typeof(entry->'id') is distinct from 'string' or (entry->>'id')=any(keys) then raise exception 'Invalid workshop record';end if;
       keys:=array_append(keys,entry->>'id');
     end loop;
   end loop;
   select count(*) into amount from jsonb_array_elements(section->'recommendations') r where r->>'state' in ('proposed','approved');
   if amount>0 then items:=items||jsonb_build_array(jsonb_build_object('actId',a->'act_id','category','Рекомендації','text','Незавершених рекомендацій: '||amount));end if;
 end if;
 if a->>'date_off' is null then
   if p_role='Слюсар' then select coalesce(jsonb_agg(w),'[]') into works from jsonb_array_elements(works) w where w->'Слюсар'=to_jsonb(p_name);end if;
   select count(*) into amount from jsonb_array_elements(works) w where w->'Слюсар' is null or w->'Слюсар' in ('null'::jsonb,'false'::jsonb,'0'::jsonb) or regexp_replace(public.traffic_attention_text(w->'Слюсар'),'^[[:space:]'||chr(160)||chr(65279)||']+|[[:space:]'||chr(160)||chr(65279)||']+$','','g')='';
   if amount>0 then items:=items||jsonb_build_array(jsonb_build_object('actId',a->'act_id','category','Виконавці','text','Робіт без призначеного виконавця: '||amount));end if;
   if p_prices and p_role<>'Слюсар' then
     details:=case when jsonb_typeof(d->'Деталі')='array' then d->'Деталі' else '[]'::jsonb end;
     select coalesce(jsonb_agg(r),'[]') into details from jsonb_array_elements(details) r where r->'Деталь' not in ('null'::jsonb,'false'::jsonb,'0'::jsonb) and regexp_replace(public.traffic_attention_text(r->'Деталь'),'^[[:space:]'||chr(160)||chr(65279)||']+|[[:space:]'||chr(160)||chr(65279)||']+$','','g')<>'';
     select count(*) into amount from jsonb_array_elements(works||details) r where not public.traffic_attention_positive_price(r->'Ціна');
     if amount>0 then items:=items||jsonb_build_array(jsonb_build_object('actId',a->'act_id','category','Ціни','text','Позицій без додатної ціни: '||amount||' — перевірте, чи це навмисно'));end if;
   end if;
   if a->'slusarsOn'='true'::jsonb and p_role in ('Адміністратор','Приймальник') then items:=items||jsonb_build_array(jsonb_build_object('actId',a->'act_id','category','Завершення робіт','text','Є позначка завершення робіт слюсарем. Перевірте готовність і зв’язок із клієнтом.'));end if;
   if d->'__payroll_pending'='true'::jsonb and p_role='Адміністратор' then items:=items||jsonb_build_array(jsonb_build_object('actId',a->'act_id','category','Збереження','text','В акті є позначка незавершеного оновлення нарахувань. Потрібна перевірка; огляд нічого не перераховує.'));end if;
 end if;
 return jsonb_build_object('permitted',permitted,'items',items);
exception when others then return jsonb_build_object('permitted',permitted,'items','[]'::jsonb,'warning','Не вдалося перевірити дані акта №'||(a->>'act_id')||'.');
end $$;

create or replace function public.traffic_attention_overview(p_role text,p_name text,p_prices boolean,p_acts boolean,p_stock boolean,p_planning boolean,p_start timestamptz,p_end timestamptz,p_category text default '',p_offset integer default 0)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb;
begin
 if p_role not in ('Адміністратор','Приймальник','Слюсар','Запчастист','Складовщик') or nullif(p_name,'') is null then raise exception 'Invalid attention scope';end if;
 if p_offset<0 or p_start is null or p_end is null or p_end<=p_start or p_end-p_start>interval '3 days' then raise exception 'Invalid attention range';end if;
 with acts as materialized (
   select a.act_id,public.traffic_attention_act_rules(jsonb_build_object('act_id',a.act_id,'pruimalnyk',a.pruimalnyk,'date_off',a.date_off,'slusarsOn',a."slusarsOn",'data',a.data),p_role,p_name,p_prices) r
   from public.acts a where p_acts and (p_role<>'Приймальник' or a.pruimalnyk=p_name)
 ), reasons as (
   select 1 source,a.act_id id,e.ordinality ordinal,e.value item from acts a cross join lateral jsonb_array_elements(a.r->'items') with ordinality e
   union all
   select 2,s.sclad_id,1,jsonb_strip_nulls(jsonb_build_object('actId',case when a.r->>'permitted'='true' then a.act_id else null end,'category','Деталі','text',s.statys||': '||coalesce(nullif(s.name,''),'Без назви')||case when s.akt>0 then ' · акт №'||s.akt else '' end))
   from public.sclad s left join acts a on a.act_id=s.akt
   where p_stock and s.statys in ('Замовити','Замовлено') and (p_role in ('Адміністратор','Запчастист','Складовщик') or a.r->>'permitted'='true')
   union all
   select 3,p.post_arxiv_id,1,jsonb_build_object('category','Планування','destination','planner','planningAt',p.data_on,'post',p.name_post,'status',p.status)
   from public.post_arxiv p where p_planning and p.data_on>=p_start and p.data_on<p_end and p.status in ('Запланований','В роботі') and (p_role='Адміністратор' or p.xto_zapusav=p_name)
 ), counts as (select item->>'category' category,count(*) amount from reasons group by 1), selected as (
   select * from reasons where p_category='' or item->>'category'=p_category order by source,id,ordinal limit 201 offset p_offset
 )
 select jsonb_build_object(
   'items',coalesce((select jsonb_agg(item order by source,id,ordinal) from (select * from selected order by source,id,ordinal limit 200) page),'[]'::jsonb),
   'counts',coalesce((select jsonb_object_agg(category,amount) from counts),'{}'::jsonb),
   'total',(select count(*) from reasons),'has_more',(select count(*)>200 from selected),
   'warnings',coalesce((select jsonb_agg(r->>'warning' order by act_id) from acts where r?'warning'),'[]'::jsonb)
 ) into result;
 return result;
end $$;
grant execute on function public.traffic_attention_overview(text,text,boolean,boolean,boolean,boolean,timestamptz,timestamptz,text,integer) to anon,authenticated;


-- SOURCE: 20261011090000_traffic_payroll_employees.sql
-- Read-only employee fields and histories for at most 200 explicitly selected acts.
-- Uses the strict JSON parser from 20261011080000_traffic_payroll_json.sql.
create or replace function public.traffic_payroll_employees(p_act_ids bigint[],p_offset integer default 0,p_employee_id bigint default null,p_name text default null)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare employee record; parsed jsonb; result jsonb:='[]'; history jsonb; selected_history jsonb; bucket record; selected_entries jsonb; projection jsonb;
begin
 if coalesce(array_length(p_act_ids,1),0) not between 1 and 200 or exists(select 1 from unnest(p_act_ids)i where i is null or i<=0) then raise exception 'Expected 1–200 act IDs';end if;
 for employee in select slyusar_id,data from public.slyusars s
  where (p_employee_id is null or s.slyusar_id=p_employee_id)
   and (p_name is null or public.payroll_json_object(to_jsonb(s.data))->>'Name'=p_name)
  order by slyusar_id offset greatest(coalesce(p_offset,0),0) limit 200 loop
  parsed:=public.payroll_json_object(to_jsonb(employee.data));history:=coalesce(nullif(parsed->'Історія','null'::jsonb),'{}'::jsonb);selected_history:='{}';
  if jsonb_typeof(history) is distinct from 'object' then raise exception 'Некоректна історія зарплати';end if;
  for bucket in select * from jsonb_each(history) loop
   if jsonb_typeof(bucket.value) is distinct from 'array' then raise exception 'Некоректна дата історії зарплати';end if;
   select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb) into selected_entries
    from jsonb_array_elements(bucket.value) with ordinality
    where value->>'Акт'=any(array(select i::text from unnest(p_act_ids)i));
   if selected_entries<>'[]'::jsonb then selected_history:=selected_history||jsonb_build_object(bucket.key,selected_entries);end if;
  end loop;
  select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) into projection from jsonb_each(parsed)
   where key in ('Name','Доступ','Склад','ПроцентРоботи','ПроцентЗапчастин');
  projection:=projection||jsonb_build_object('Історія',selected_history);
  result:=result||jsonb_build_array(jsonb_build_object('slyusar_id',employee.slyusar_id,'data',projection));
 end loop;
 return result;
end $$;
revoke all on function public.traffic_payroll_employees(bigint[],integer,bigint,text) from public;
grant execute on function public.traffic_payroll_employees(bigint[],integer,bigint,text) to anon,authenticated;
notify pgrst,'reload schema';


-- SOURCE: 20261011100000_traffic_editor_references.sql

-- Existing dictionaries only. Search results are candidates, never a complete dictionary.
create or replace function public.traffic_editor_references(p_query text default '',p_names text[] default '{}',p_work_ids text[] default '{}',p_detail_ids bigint[] default '{}',p_voice boolean default false)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb;
begin
 if length(p_query)>2000 or cardinality(p_names)>200 or cardinality(p_work_ids)>200 or cardinality(p_detail_ids)>200 then raise exception 'Editor lookup too large';end if;
 with entries as (
   select 'work' kind,work_id::text id,public.traffic_reference_name(to_jsonb(data)) name,''::text catalog from public.works
   union all select 'detail',detail_id::text,public.traffic_reference_name(to_jsonb(data)),'' from public.details
   union all select 'shop',shop_id::text,coalesce(public.sto_read_object_v1(data::jsonb)->>'Name',case when jsonb_typeof(data::jsonb)='string' then data::jsonb#>>'{}' end,''),'' from public.shops
   union all select 'stock',sclad_id::text,name,coalesce(part_number,'') from public.sclad where p_voice
 ), matched as (
   select *,case when name=any(p_names) or (kind='work' and id=any(p_work_ids)) or (kind='detail' and id=any(select unnest(p_detail_ids)::text)) then 0
     when lower(name)=lower(btrim(p_query)) or lower(id)=lower(btrim(p_query)) or (p_voice and length(name)>=3 and strpos(lower(p_query),lower(name))>0) then 1 else 2 end rank,
     case when p_voice then (select coalesce(sum(length(token)),0) from regexp_split_to_table(lower(p_query),'[^[:alnum:]а-яіїєґ]+') token where length(token)>=3 and strpos(lower(name),left(token,greatest(3,length(token)-2)))>0) else 0 end voice_score
   from entries where name=any(p_names) or (kind='work' and id=any(p_work_ids)) or (kind='detail' and id=any(select unnest(p_detail_ids)::text))
    or (kind='shop' and btrim(p_query)='' and cardinality(p_names)=0 and cardinality(p_work_ids)=0 and cardinality(p_detail_ids)=0)
    or (btrim(p_query)<>'' and (strpos(lower(name),lower(btrim(p_query)))>0 or (kind='work' and strpos(lower(id),lower(btrim(p_query)))>0)
      or (p_voice and exists(select 1 from regexp_split_to_table(lower(p_query),'[^[:alnum:]а-яіїєґ]+') token where length(token)>=3 and strpos(lower(name),left(token,greatest(3,length(token)-2)))>0))))
 ), ranked as (select *,row_number() over(partition by kind order by rank,voice_score desc,id) rn from matched)
 select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'id',id,'name',name,'catalog',catalog) order by kind,rank,voice_score desc,id),'[]') into result
 from ranked where rank=0 or rn<=case when p_voice then 80 else 50 end;
 return result;
end;$$;
revoke all on function public.traffic_editor_references(text,text[],text[],bigint[],boolean) from public;
grant execute on function public.traffic_editor_references(text,text[],text[],bigint[],boolean) to anon,authenticated;
create or replace function public.traffic_editor_act_quantities(p_act_id bigint)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare raw jsonb; doc jsonb; details jsonb; quantities jsonb;
begin
 select to_jsonb(a.data) into raw from public.acts a where a.act_id=p_act_id;
 if not found then return null;end if;
 if jsonb_typeof(raw)='string' then raw:=(raw#>>'{}')::jsonb;end if;
 if jsonb_typeof(raw) is distinct from 'object' then raise exception 'Некоректні дані акту для перевірки кількості';end if;
 doc:=raw;details:=coalesce(nullif(doc->'Деталі','null'::jsonb),'[]'::jsonb);
 if jsonb_typeof(details) is distinct from 'array' then raise exception 'Некоректний список деталей акту';end if;
 select coalesce(jsonb_agg(jsonb_build_object('sclad_id',item->'sclad_id','Кількість',item->'Кількість')),'[]'::jsonb) into quantities from jsonb_array_elements(details)item;
 return jsonb_build_object('Деталі',quantities,'__act_revision',doc->'__act_revision');
end;
$$;
revoke all on function public.traffic_editor_act_quantities(bigint) from public;
grant execute on function public.traffic_editor_act_quantities(bigint) to anon,authenticated;


-- SOURCE: 20261011110000_traffic_ai_financial.sql
-- Atlas financial aggregates over existing rows. No new tables or writes.
create or replace function public.traffic_ai_parse_float(v jsonb)
returns double precision language plpgsql immutable security invoker set search_path=pg_catalog,public as $$
declare value text; matched text; mantissa text; digits text; exponent_text text; decimal_exponent numeric;
begin
 value:=public.traffic_search_trim(public.traffic_search_string(v));
 matched:=substring(ltrim(value,E' \t\n\r') from '^[+-]?(?:[0-9]+\.?[0-9]*|\.[0-9]+)(?:[eE][+-]?[0-9]+)?');
 if matched is null then
  if ltrim(value) ~ '^[+-]?Infinity' then raise exception 'Nonfinite amount in Atlas financial report'; end if;
  return 0;
 end if;
 begin
  return matched::double precision;
 exception when numeric_value_out_of_range then
  -- JS parseFloat underflows to zero; PostgreSQL raises instead. Distinguish
  -- tiny finite values from overflow, which must still reject a financial report.
  mantissa:=regexp_replace(split_part(lower(matched),'e',1),'^[+-]','');
  digits:=replace(mantissa,'.','');
  exponent_text:=nullif(split_part(lower(matched),'e',2),'');
  begin decimal_exponent:=coalesce(exponent_text::numeric,0);
  exception when numeric_value_out_of_range then
   if left(exponent_text,1)='-' then return 0;end if;
   raise;
  end;
  decimal_exponent:=decimal_exponent+length(split_part(mantissa,'.',1))-(length(digits)-length(ltrim(digits,'0')))-1;
  if decimal_exponent < -308 then return 0;end if;
  raise;
 end;
end $$;
create or replace function public.traffic_ai_financial(p_current timestamptz,p_previous timestamptz)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare r record; body jsonb; amount double precision; is_current boolean; expense_date timestamptz;
 current_revenue double precision:=0; previous_revenue double precision:=0;
 current_expenses double precision:=0; previous_expenses double precision:=0;
 current_count bigint:=0; previous_count bigint:=0;
begin
 if p_current is null or p_previous is null or p_previous>p_current then raise exception 'Invalid financial interval';end if;
 for r in select act_id,date_on,data from public.acts where date_on>=p_previous order by act_id loop
  -- Preserve existing Atlas revenue fields and its object-only data semantics.
  body:=case when jsonb_typeof(r.data::jsonb)='object' then r.data::jsonb else '{}'::jsonb end;
  amount:=public.traffic_ai_parse_float(body->'СумаРобіт')+public.traffic_ai_parse_float(body->'СумаДеталей');
  if r.date_on>=p_current then current_revenue:=current_revenue+amount;current_count:=current_count+1;
  else previous_revenue:=previous_revenue+amount;previous_count:=previous_count+1;end if;
 end loop;
 for r in select to_jsonb(v) row_data from public.vutratu v order by vutratu_id loop
  body:=r.row_data;
  -- Current project schema uses dataOnn; retain compatibility with older installations.
  -- The legacy .gte(date, boundary) excludes NULL dates; they must not abort
  -- an otherwise valid report just because an old row has no timestamp.
  if coalesce(body->>'data_vutratu',body->>'dataOnn') is null then continue;end if;
  expense_date:=case when body ? 'data_vutratu' then (body->>'data_vutratu')::timestamptz
    else (body->>'dataOnn')::timestamp at time zone 'Europe/Kyiv' end;
  if expense_date<p_previous then continue;end if;
  is_current:=expense_date>=p_current;
  amount:=public.traffic_ai_parse_float(body->'suma');
  if is_current then current_expenses:=current_expenses+amount;
  else previous_expenses:=previous_expenses+amount;end if;
 end loop;
 return jsonb_build_object('current',jsonb_build_object('revenue',current_revenue,'expenses',current_expenses,'acts_count',current_count),
  'previous',jsonb_build_object('revenue',previous_revenue,'expenses',previous_expenses,'acts_count',previous_count),
  'scope',jsonb_build_object('current_from',p_current,'previous_from',p_previous),'complete',true);
end $$;
revoke all on function public.traffic_ai_parse_float(jsonb),public.traffic_ai_financial(timestamptz,timestamptz) from public;
grant execute on function public.traffic_ai_parse_float(jsonb),public.traffic_ai_financial(timestamptz,timestamptz) to anon,authenticated;
-- Complete VIP grouping before the requested top-N display limit.
create or replace function public.traffic_ai_vip(p_since timestamptz,p_limit integer default 20)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 with source as (
  select a.act_id,a.client_id,a.date_on,case when jsonb_typeof(a.data::jsonb)='object' then a.data::jsonb else '{}'::jsonb end body
  from public.acts a where a.date_on>=p_since and a.client_id is not null and a.client_id<>0
 ), grouped as (
  select client_id,count(*) acts,
   sum(public.traffic_ai_parse_float(body->'СумаРобіт')+public.traffic_ai_parse_float(body->'СумаДеталей') order by date_on desc,act_id desc) revenue,
   (array_agg(body->'ПІБ' order by date_on desc,act_id desc))[1] name,
   (array_agg(body->'Телефон' order by date_on desc,act_id desc))[1] phone,max(date_on) last_visit
  from source group by client_id
 ), page as(select * from grouped order by revenue desc,last_visit desc,client_id limit greatest(1,least(coalesce(p_limit,20),200)))
 select jsonb_build_object('items',coalesce((select jsonb_agg(jsonb_build_array(client_id,jsonb_build_object(
   'acts',acts,'revenue',revenue,'name',case when public.traffic_search_truthy(name) then name else to_jsonb('—'::text) end,
   'phone',case when public.traffic_search_truthy(phone) then phone else to_jsonb(''::text) end,'lastVisit',last_visit)) order by revenue desc,last_visit desc,client_id) from page),'[]'::jsonb),
 'total_clients',(select count(*) from grouped),'has_more',(select count(*) from grouped)>greatest(1,least(coalesce(p_limit,20),200)),
 'since',p_since,'complete',true);
$$;
revoke all on function public.traffic_ai_vip(timestamptz,integer) from public;
grant execute on function public.traffic_ai_vip(timestamptz,integer) to anon,authenticated;
-- Staff ranking aggregates; employee payroll histories never leave this function.
create or replace function public.traffic_ai_staff_ranking(p_since timestamptz,p_after bigint default null)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 with staff as materialized (
  select s.slyusar_id,to_jsonb(s)->'post_sluysar' post,
   case when jsonb_typeof(s.data::jsonb)='object' then s.data::jsonb else '{}'::jsonb end body from public.slyusars s
 ), acts as (
  select a.act_id,a.date_off,case when jsonb_typeof(a.data::jsonb)='object' then a.data::jsonb else '{}'::jsonb end body
  from public.acts a where a.date_on>=p_since
 ), matched as (
  select a.*,s.slyusar_id from acts a join lateral (
   select s.slyusar_id from staff s where jsonb_typeof(s.body->'Name')='string'
    and jsonb_typeof(a.body->'Слюсар')='string' and a.body->>'Слюсар'<>''
    and lower(s.body->>'Name')=lower(a.body->>'Слюсар') order by s.slyusar_id limit 1
  ) s on true
 ), totals as (
  select slyusar_id,count(*) acts,count(*) filter(where date_off is null) open_acts,
   sum(public.traffic_ai_parse_float(body->'СумаРобіт')+public.traffic_ai_parse_float(body->'СумаДеталей') order by act_id) revenue
  from matched group by slyusar_id
 ), candidates as (select * from staff where p_after is null or slyusar_id>p_after order by slyusar_id limit 201),
 page as (select * from candidates order by slyusar_id limit 200)
 select jsonb_build_object('items',coalesce((select jsonb_agg(jsonb_build_object('slyusar_id',p.slyusar_id,'post_sluysar',p.post,
  'data',(select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(p.body) where key in ('Name','Спеціалізація','Рейтинг')),
  '__stats',jsonb_build_object('acts',coalesce(t.acts,0),'revenue',coalesce(t.revenue,0),'openActs',coalesce(t.open_acts,0))) order by p.slyusar_id)
  from page p left join totals t using(slyusar_id)),'[]'::jsonb),
  'has_more',(select count(*)>200 from candidates),'next_cursor',(select max(slyusar_id) from page),'since',p_since);
$$;
revoke all on function public.traffic_ai_staff_ranking(timestamptz,bigint) from public;
grant execute on function public.traffic_ai_staff_ranking(timestamptz,bigint) to anon,authenticated;


-- SOURCE: 20261011120000_traffic_payroll_directory.sql
-- Initial accounting directory: no payroll histories, credentials or act documents.
create or replace function public.traffic_payroll_directory(p_after bigint default null)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 with candidates as (
  select s.slyusar_id,public.traffic_json_object(s.data::jsonb) body from public.slyusars s
  where p_after is null or s.slyusar_id>p_after order by s.slyusar_id limit 201
 ), page as(select * from candidates order by slyusar_id limit 200)
 select jsonb_build_object('items',coalesce((select jsonb_agg(jsonb_build_object('slyusar_id',p.slyusar_id,
  'data',(select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(p.body)
          where key in ('Name','ПроцентРоботи'))) order by p.slyusar_id) from page p),'[]'::jsonb),
 'has_more',(select count(*)>200 from candidates),'next_cursor',(select max(slyusar_id) from page),
 'pending_count',case when p_after is null then (select count(*) from public.acts a
  where public.traffic_json_object(a.data::jsonb)->'__payroll_pending'='true'::jsonb
    and public.traffic_json_object(a.data::jsonb)->'Заморожений' is distinct from 'true'::jsonb) else null end);
$$;
revoke all on function public.traffic_payroll_directory(bigint) from public;
grant execute on function public.traffic_payroll_directory(bigint) to anon,authenticated;


-- SOURCE: 20261011120000_traffic_shop_report_page.sql
-- Read-only details-by-act report. All filters and totals precede pagination.

create or replace function public.traffic_shop_date(v text) returns text
language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare s text; m text[]; y text;
begin
 if coalesce(v,'')='' then return ''; end if;
 m:=regexp_match(btrim(v),'^(\d{4})-(\d{2})-(\d{2})($|[T\s])');
 if m is not null then return m[1]||'-'||m[2]||'-'||m[3]; end if;
 s:=regexp_replace(normalize(btrim(v),NFKC),'[^0-9.\-/]','','g');
 m:=regexp_match(s,'^(\d{4})[.\-/](\d{1,2})[.\-/](\d{1,2})$');
 if m is not null then return m[1]||'-'||lpad(m[2],2,'0')||'-'||lpad(m[3],2,'0'); end if;
 m:=regexp_match(s,'^(\d{1,2})[.\-/](\d{1,2})[.\-/](\d{2,4})$');
 if m is null then return ''; end if;
 y:=m[3]; if length(y)=2 then y:=(case when y::integer>=70 then '19' else '20' end)||y;end if;
 return y||'-'||lpad(m[2],2,'0')||'-'||lpad(m[1],2,'0');
end $$;

create or replace function public.traffic_shop_report_page(p_filter jsonb default '{}'::jsonb,p_offset integer default 0,p_limit integer default 100)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb;
begin
 if p_offset<0 or p_limit<1 or p_limit>200 then raise exception 'Invalid report page'; end if;
 with shops as materialized (
  select shop_id,public.sto_read_object_v1(to_jsonb(data)) body from public.shops
 ), history as materialized (
  select s.shop_id,s.body->>'Name' shop,h.key date_open,e.entry,e.ord entry_ord
  from shops s cross join lateral jsonb_each(case when jsonb_typeof(s.body->'Історія')='object' then s.body->'Історія' else '{}'::jsonb end) h
  cross join lateral jsonb_array_elements(case when jsonb_typeof(h.value)='array' then h.value else '[]'::jsonb end) with ordinality e(entry,ord)
  where public.traffic_search_truthy(s.body->'Name')
 ), raw as (
  select h.shop_id,h.shop,h.date_open,h.entry_ord,h.entry-'Деталі' entry,d.detail,d.detail_ord,a.act_id,a.date_off,
   public.sto_read_object_v1(to_jsonb(a.data)) act_body,
   n.sclad_id stock_id,to_jsonb(n) stock_row,public.sto_read_object_v1(to_jsonb(n)->'data') stock_body
  from history h
  cross join lateral jsonb_array_elements(case when jsonb_typeof(h.entry->'Деталі')='array' then h.entry->'Деталі' else '[]'::jsonb end) with ordinality d(detail,detail_ord)
  left join public.acts a on a.act_id::text=h.entry->>'Акт'
  left join public.sclad n on n.sclad_id::text=d.detail->>'sclad_id'
 ), values_normalized as (
  select *,coalesce(public.traffic_search_number(detail->'Кількість'),0) quantity,
   coalesce(public.traffic_search_number(detail->'Ціна'),0) price,
   case when stock_id is not null then coalesce(public.traffic_search_number(
    case when stock_body ? 'price' then stock_body->'price'
     when jsonb_typeof(stock_row->'data')='string' and stock_body<>'{}'::jsonb then '0'::jsonb
     else stock_row->'price' end),0) end purchase_price,
   public.traffic_search_number(coalesce(stock_body->'scladNomer',stock_row->'scladNomer')) warehouse,
   greatest(coalesce(public.traffic_search_number(act_body->'Знижка'),0),0) discount,
   case when act_id is not null then coalesce(date_off::text,'') else coalesce(entry->>'ДатаЗакриття','') end date_close,
   public.traffic_search_truthy(entry->'Розрахунок') is_paid,
   coalesce(entry->>'Розрахунок','') payment_date,
   coalesce(detail->>'Найменування','') item,coalesce(detail->>'Каталог','') catalog
  from raw
 ), calculated as (
  select *,quantity*price total,
   case when purchase_price is not null then price*(case when discount>0 then 1-discount/100 else 1 end)*quantity-purchase_price*quantity end margin,
   case coalesce(p_filter->>'dateMode','open') when 'close' then date_close when 'paid' then payment_date else date_open end target_date
  from values_normalized
 ), matches as materialized (
  select *,public.traffic_shop_date(target_date) sort_date from calculated
  where (coalesce(p_filter->>'dateMode','open')='open' or target_date<>'')
   and (coalesce(p_filter->>'from','')='' and coalesce(p_filter->>'to','')='' or
    public.traffic_shop_date(target_date)<>'' and
    (coalesce(p_filter->>'from','')='' or public.traffic_shop_date(target_date)>=p_filter->>'from') and
    (coalesce(p_filter->>'to','')='' or public.traffic_shop_date(target_date)<=p_filter->>'to'))
   and (coalesce(p_filter->>'item','')='' or strpos(lower(item),lower(p_filter->>'item'))>0)
   and (coalesce(p_filter->>'catalog','')='' or strpos(lower(catalog),lower(p_filter->>'catalog'))>0 or
    regexp_replace(lower(normalize(p_filter->>'catalog',NFKC)),'[^[:alnum:]]','','g')<>'' and
    strpos(regexp_replace(lower(normalize(catalog,NFKC)),'[^[:alnum:]]','','g'),regexp_replace(lower(normalize(p_filter->>'catalog',NFKC)),'[^[:alnum:]]','','g'))>0)
   and (coalesce(p_filter->>'status','all')='all' or (p_filter->>'status'='closed')=(date_close<>''))
   and (coalesce(p_filter->>'payment','all')='all' or (p_filter->>'payment'='paid')=is_paid)
 ), filtered as materialized (
  select * from matches where p_filter->>'warehouse' is null or warehouse=public.traffic_search_number(p_filter->'warehouse')
 ), page as materialized (
  select * from filtered order by sort_date desc,shop_id,date_open,entry_ord,detail_ord offset p_offset limit p_limit
 ), page_entries as (
  select distinct p.shop_id,p.shop,p.date_open,p.entry_ord,h.entry from page p
  join history h on h.shop_id=p.shop_id and h.date_open=p.date_open and h.entry_ord=p.entry_ord
 ), page_days as (
  select shop_id,shop,date_open,jsonb_agg(entry order by entry_ord) entries from page_entries group by shop_id,shop,date_open
 ), page_shops as (
  select shop_id,jsonb_build_object('Name',shop,'Історія',jsonb_object_agg(date_open,entries)) data from page_days group by shop_id,shop
 )
 select jsonb_build_object(
  'items',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
   'rowId',concat(shop_id,':',date_open,':',entry_ord,':',detail_ord),'shopId',shop_id,
   'dateOpen',date_open,'dateClose',date_close,'act',entry->>'Акт','automobile',coalesce(entry->>'Автомобіль',''),
   'shop',shop,'item',item,'catalog',catalog,'quantity',quantity,'price',price,'purchasePrice',purchase_price,
   'total',total,'margin',margin,'discountPercent',discount,'isPaid',is_paid,'paymentDate',payment_date,
   'sclad_id',stock_id,'scladNomer',warehouse,'isClosed',date_close<>'',
   'zapchastystName',(select public.sto_read_object_v1(to_jsonb(s.data))->>'Name' from public.slyusars s
    where s.slyusar_id::text=coalesce(stock_body->>'xto_zamovuv',stock_row->>'xto_zamovuv'))
  )) order by sort_date desc,shop_id,date_open,entry_ord,detail_ord) from page),'[]'::jsonb),
  'shops',coalesce((select jsonb_agg(to_jsonb(s) order by shop_id) from page_shops s),'[]'::jsonb),
  'totalCount',(select count(*) from filtered),
  'totals',(select jsonb_build_object('sale',coalesce(sum(total),0),'purchase',coalesce(sum(coalesce(purchase_price,0)*quantity),0),'margin',coalesce(sum(margin),0)) from filtered),
  'warehouses',coalesce((select jsonb_agg(w order by w) from (select distinct warehouse w from matches where warehouse<>0) x),'[]'::jsonb)
 ) into result;
 return result;
end $$;
revoke all on function public.traffic_shop_report_page(jsonb,integer,integer) from public;
grant execute on function public.traffic_shop_report_page(jsonb,integer,integer) to anon,authenticated;


-- SOURCE: 20261011121131_traffic_act_infinite_scroll.sql
-- Requires traffic_act_search and its read helpers. Keeps the old RPC for older clients.

create or replace function public.traffic_act_search_page_v2(
 p_from timestamptz default null,p_to timestamptz default null,p_mode text default null,
 p_filters jsonb default '[]',p_offset integer default 0,p_sort text default 'id',p_limit integer default 50
) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
begin
 if p_limit is null or p_limit not in (5,50) then raise exception 'Invalid page size';end if;
 if p_offset<0 or p_offset is null or p_sort not in ('id','open','created','closed') or p_sort is null then raise exception 'Invalid search page';end if;
 if jsonb_typeof(p_filters)<>'array' or jsonb_array_length(p_filters)>50 then raise exception 'Invalid search filters';end if;
 if p_mode is not null and p_mode not in ('open','closed','frozen') then raise exception 'Invalid search mode';end if;
 return (with candidates as materialized (
  select a.act_id,a.date_on,a.date_off,to_jsonb(a) a,cl.client_id,cl.data::jsonb client_data,c.cars_id,c.data::jsonb car_data
  from public.acts a left join public.clients cl on cl.client_id=a.client_id left join public.cars c on c.cars_id=a.cars_id
  where case p_mode when 'open' then a.date_off is null when 'closed' then a.date_off is not null when 'frozen' then true
    else p_from is not null and p_to is not null and a.date_on>=p_from and a.date_on<=p_to end
   and case when p_mode='frozen' then public.sto_read_object_v1(a.data::jsonb)->'Заморожений'='true'::jsonb
     when p_mode in ('open','closed') then coalesce(public.sto_read_object_v1(a.data::jsonb)->'Заморожений'<>'true'::jsonb,true) else true end
 ), matched as materialized (
  select * from candidates where public.traffic_act_search_match(a,client_data,car_data,p_filters)
 ), page as (
  select * from matched order by
    case when p_sort='open' then (date_off is null)::integer end desc nulls last,
    case when p_sort='closed' then (date_off is not null)::integer end desc nulls last,
    case when p_sort='closed' then coalesce(date_off,date_on,'epoch'::timestamptz) when p_sort='created' then coalesce(date_on,'epoch'::timestamptz) end desc nulls last,
    act_id desc offset p_offset limit p_limit
 ) select jsonb_build_object(
 'items',coalesce((select jsonb_agg(
   (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(p.a) where key=any(array[
     'act_id','date_on','date_off','cars_id','client_id','pruimalnyk','slusarsOn','sms','avans','rosraxovano',
     'contrAgent_act','contrAgent_act_data','contrAgent_raxunok','contrAgent_raxunok_data','total','amount']))
   || jsonb_build_object('__sto_projection','act-search-v1','data',
     case when jsonb_typeof(public.sto_act_list_data_v1(p.a->'data'))='object' then public.sto_act_list_data_v1(p.a->'data')-'Роботи'-'Деталі' else p.a->'data' end)
   || case when p.a ? 'info' then jsonb_build_object('info',case when jsonb_typeof(public.sto_act_list_data_v1(p.a->'info'))='object' then public.sto_act_list_data_v1(p.a->'info')-'Роботи'-'Деталі' else p.a->'info' end) else '{}'::jsonb end
   || case when p.a ? 'details' then jsonb_build_object('details',case when jsonb_typeof(public.sto_act_list_data_v1(p.a->'details'))='object' then public.sto_act_list_data_v1(p.a->'details')-'Роботи'-'Деталі' else p.a->'details' end) else '{}'::jsonb end
 order by
    case when p_sort='open' then (p.date_off is null)::integer end desc nulls last,
    case when p_sort='closed' then (p.date_off is not null)::integer end desc nulls last,
    case when p_sort='closed' then coalesce(p.date_off,p.date_on,'epoch'::timestamptz) when p_sort='created' then coalesce(p.date_on,'epoch'::timestamptz) end desc nulls last,
    p.act_id desc
 ) from page p),'[]'::jsonb),
 'clients',coalesce((select jsonb_agg(distinct jsonb_build_object('client_id',client_id,'data',
   (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(public.sto_read_object_v1(client_data)) where key=any(array['ПІБ','Телефон'])))) from page where client_id is not null),'[]'::jsonb),
 'cars',coalesce((select jsonb_agg(distinct jsonb_build_object('cars_id',cars_id,'data',
   (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(public.sto_read_object_v1(car_data)) where key=any(array['Номер авто','Держ. номер','plate','number','Авто','Автомобіль','auto','car','name','Марка','brand','make','Модель','model'])))) from page where cars_id is not null),'[]'::jsonb),
 'total',(select count(*) from candidates),'matched',(select count(*) from matched),
 'has_more',p_offset+p_limit<(select count(*) from matched),
 'next_offset',case when p_offset+p_limit<(select count(*) from matched) then p_offset+p_limit else null end
 ));
end;
$$;
revoke all on function public.traffic_act_search_page_v2(timestamptz,timestamptz,text,jsonb,integer,text,integer) from public;
grant execute on function public.traffic_act_search_page_v2(timestamptz,timestamptz,text,jsonb,integer,text,integer) to anon,authenticated;


notify pgrst, 'reload schema';


-- SOURCE: 20261011130000_traffic_payroll_report.sql
-- Read-only report pages. Formulas mirror zarplata.ts; full histories never leave the server.
create or replace function public.traffic_payroll_iso(p_value text)
returns text language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare s text; m text[];
begin
 m:=regexp_match(btrim(coalesce(p_value,'')),'^([0-9]{4})-([0-9]{2})-([0-9]{2})($|[T[:space:]])');
 if m is not null then return m[1]||'-'||m[2]||'-'||m[3];end if;
 s:=regexp_replace(normalize(coalesce(p_value,''),NFKC),'[^0-9./-]','','g');
 m:=regexp_match(s,'^([0-9]{4})[./-]([0-9]{1,2})[./-]([0-9]{1,2})$');
 if m is not null then return m[1]||'-'||lpad(m[2],2,'0')||'-'||lpad(m[3],2,'0');end if;
 m:=regexp_match(s,'^([0-9]{1,2})[./-]([0-9]{1,2})[./-]([0-9]{2,4})$');
 if m is not null then
  if length(m[3])=2 then m[3]:=case when m[3]::int>=70 then '19' else '20' end||m[3];end if;
  return m[3]||'-'||lpad(m[2],2,'0')||'-'||lpad(m[1],2,'0');
 end if;
 return '';
end $$;

create or replace function public.traffic_payroll_validate(p_data jsonb)
returns boolean language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare history jsonb:=coalesce(nullif(p_data->'Історія','null'::jsonb),'{}'::jsonb);bucket jsonb;entry jsonb;seen text[]:='{}';act text;
begin
 if jsonb_typeof(history) is distinct from 'object' then raise exception 'Некоректна історія зарплат';end if;
 for bucket in select value from jsonb_each(history) loop
  if jsonb_typeof(bucket) is distinct from 'array' then raise exception 'Некоректна дата історії зарплат';end if;
  for entry in select value from jsonb_array_elements(bucket) loop
   act:=entry->>'Акт';if act is null then raise exception 'Нарахування без номера акта';end if;
   if act=any(seen) then raise exception 'Дублікати зарплати за актом %',act;end if;seen:=array_append(seen,act);
   if entry?'Записи' and entry->'Записи'<>'null'::jsonb then
    if jsonb_typeof(entry->'Записи') is distinct from 'array' then raise exception 'Некоректний список робіт';end if;
    if exists(select 1 from jsonb_array_elements(entry->'Записи')r where nullif(r->>'recordId','') is not null group by r->>'recordId' having count(*)>1) then raise exception 'Повторні ідентифікатори робіт в акті %',act;end if;
   end if;
  end loop;
 end loop;
 return true;
end $$;

create or replace function public.traffic_payroll_report(p_filters jsonb,p_offset integer default 0)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb; selected_name text:=coalesce(p_filters->>'name','');mode text:=coalesce(p_filters->>'mode','open');
 from_day text:=public.traffic_payroll_iso(p_filters->>'from');to_day text:=public.traffic_payroll_iso(p_filters->>'to');
begin
 if mode not in ('open','close','paid') then raise exception 'Невідомий режим дат';end if;
 if to_day='' then raise exception 'Потрібна кінцева дата звіту';end if;
 -- Validate selected employees before narrowing dates: hidden duplicates must not become payable.
 perform public.traffic_payroll_validate(public.payroll_json_object(to_jsonb(s.data))) from public.slyusars s
  where selected_name='' or public.payroll_json_object(to_jsonb(s.data))->>'Name'=selected_name;
 with employees as materialized (
  select s.slyusar_id id,public.payroll_json_object(to_jsonb(s.data)) doc from public.slyusars s
  where selected_name='' or public.payroll_json_object(to_jsonb(s.data))->>'Name'=selected_name
 ), entries as materialized (
  select e.id,e.doc->>'Name' name,e.doc->'ПроцентРоботи' percent,h.key history_day,x.value entry,x.ordinality entry_order,
   a.act_id existing_act_id,a.date_off,(case when a.act_id is null then '{}'::jsonb else public.payroll_json_object(to_jsonb(a.data)) end)->'Заморожений'='true'::jsonb frozen,
   (case when a.act_id is null then '{}'::jsonb else public.payroll_json_object(to_jsonb(a.data)) end)->'__payroll_pending'='true'::jsonb pending,
   case when a.act_id is not null then coalesce(a.date_off::text,'') else coalesce(x.value->>'ДатаЗакриття','') end close_day,
   case when a.act_id is not null then a.date_off is not null else coalesce(x.value->>'ДатаЗакриття','')<>'' end closed
  from employees e cross join lateral jsonb_each(coalesce(nullif(e.doc->'Історія','null'::jsonb),'{}'::jsonb))h
   cross join lateral jsonb_array_elements(h.value) with ordinality x
   left join public.acts a on a.act_id::text=x.value->>'Акт'
 ), expanded as (
  select e.*,case when jsonb_array_length(coalesce(nullif(entry->'Записи','null'::jsonb),'[]'::jsonb))>0 then 'work'
   when entry?'СуммаРоботи' then 'receiver' when entry?'СуммаЗапчастин' then 'parts' else 'unknown' end kind,
   r.value row_data,r.ordinality::integer-1 work_index
  from entries e cross join lateral jsonb_array_elements(case when jsonb_array_length(coalesce(nullif(entry->'Записи','null'::jsonb),'[]'::jsonb))>0 then entry->'Записи' else '[null]'::jsonb end) with ordinality r
  where not coalesce(frozen,false)
 ), value_rows as (
  select *,case when kind='work' then coalesce(row_data->>'Розраховано','') else coalesce(entry->>'Розраховано','') end paid_day,
   case when kind='work' then coalesce(row_data->>'Робота','') when kind='receiver' then '-' else 'Запчастини' end work,
   coalesce(public.traffic_search_number(row_data->'Ціна'),0)*coalesce(public.traffic_search_number(row_data->'Кількість'),0) work_total,
   coalesce(public.traffic_search_number(row_data->'Зарплата'),0) work_salary,
   coalesce(public.traffic_search_number(entry->'СуммаРоботи'),0) work_sum,
   coalesce(public.traffic_search_number(entry->'СуммаЗапчастин'),0) parts_sum,
   coalesce(public.traffic_search_number(entry->'ЗарплатаРоботи'),0) receiver_work_salary,
   coalesce(public.traffic_search_number(entry->'ЗарплатаЗапчастин'),0) parts_salary
  from expanded where kind<>'unknown' and not(kind='work' and coalesce(row_data->'Кількість'='0'::jsonb,false) and not public.traffic_search_truthy(row_data->'Зарплата'))
 ), calculated as (
  select *,case when kind='work' then work_total when kind='receiver' then work_sum+parts_sum else parts_sum end revenue,
   case when kind='work' then work_salary when kind='receiver' then (case when work_sum>0 then receiver_work_salary else 0 end)+parts_salary else case when parts_sum>0 then parts_salary else 0 end end salary,
   public.traffic_payroll_iso(case when mode='paid' then paid_day when mode='close' then close_day else history_day end) filter_day
  from value_rows
 ), date_matches as materialized (
  select * from calculated where filter_day<>'' and (from_day='' or filter_day>=from_day) and filter_day<=to_day
 ), matches as materialized (
  select * from date_matches where
   (coalesce(p_filters->>'act','')='' or entry->>'Акт'=p_filters->>'act')
   and (coalesce(p_filters->>'work','')='' or strpos(lower(work),lower(p_filters->>'work'))>0)
   and (coalesce(p_filters->>'payment','all')='all' or (p_filters->>'payment'='paid' and paid_day<>'') or (p_filters->>'payment'='unpaid' and paid_day=''))
   and (coalesce(p_filters->>'status','all')='all' or (p_filters->>'status'='closed' and closed) or (p_filters->>'status'='open' and not closed))
   and (coalesce(p_filters->>'percentage','all')='all' or (kind='work' and salary<>0 and coalesce(public.traffic_search_number(percent),0)<>0 and
    case when p_filters->>'percentage'='higher' then (case when revenue>0 then salary/revenue*100 else 0 end)>public.traffic_search_number(percent)
     else (case when revenue>0 then salary/revenue*100 else 0 end)<public.traffic_search_number(percent) end))
 ), page as materialized (
  select * from matches order by coalesce(substring(entry->>'Акт' from '^[-+]?[0-9]+')::numeric,0) desc,
   public.traffic_payroll_iso(case when mode='paid' then paid_day else history_day end) desc,id,history_day,entry_order,work_index
   offset greatest(coalesce(p_offset,0),0) limit 50
 ), page_entries as (
  select distinct id,name,percent,history_day,entry,entry_order from page
 ), histories as (
  select id,name,percent,history_day,jsonb_agg(entry order by entry_order) entries from page_entries group by id,name,percent,history_day
 ), rows as (
  select id,jsonb_build_object('slyusar_id',id,'data',jsonb_build_object('Name',name,'ПроцентРоботи',percent,'Історія',jsonb_object_agg(history_day,entries))) row from histories group by id,name,percent
 )
 select jsonb_build_object(
  'employees',coalesce((select jsonb_agg(row order by id) from rows),'[]'::jsonb),
  'keys',coalesce((select jsonb_agg(jsonb_build_array(id,history_day,entry->>'Акт',case when kind='work' then work_index else null end)) from page),'[]'::jsonb),
  'statuses',coalesce((select jsonb_agg(jsonb_build_object('actId',id,'dateOff',date_off,'isClosed',closed,'isFrozen',false,'payrollPending',pending)) from (select distinct existing_act_id::text id,date_off,closed,pending from page where existing_act_id is not null)s),'[]'::jsonb),
  'total',(select count(*) from matches),'revenue',coalesce((select sum(revenue) from matches),0),'salary',coalesce((select sum(salary) from matches),0),
  'has_more',(select count(*) from matches)>greatest(coalesce(p_offset,0),0)+50,
  'acts',coalesce((select jsonb_agg(act order by coalesce(substring(act from '^[-+]?[0-9]+')::numeric,0) desc) from(select distinct entry->>'Акт' act from date_matches)a),'[]'::jsonb),
  'works',coalesce((select jsonb_agg(work order by work) from(select distinct work from date_matches order by work limit 150)w),'[]'::jsonb)
 ) into result;
 return result;
end $$;
revoke all on function public.traffic_payroll_iso(text),public.traffic_payroll_validate(jsonb),public.traffic_payroll_report(jsonb,integer) from public;
grant execute on function public.traffic_payroll_iso(text),public.traffic_payroll_validate(jsonb),public.traffic_payroll_report(jsonb,integer) to anon,authenticated;
notify pgrst,'reload schema';


-- SOURCE: 20261011140000_traffic_ai_workload.sql
-- Complete workload statistics; only seven daily and 24 hourly buckets leave PostgreSQL.
create or replace function public.traffic_ai_workload(p_since timestamptz,p_timezone text)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 with source as (
  select act_id,date_on,
   extract(dow from case when pg_typeof(date_on)='timestamp without time zone'::regtype then date_on::timestamp else date_on::timestamptz at time zone p_timezone end)::integer dow,
   extract(hour from case when pg_typeof(date_on)='timestamp without time zone'::regtype then date_on::timestamp else date_on::timestamptz at time zone p_timezone end)::integer as "hour",
   (case when pg_typeof(date_on)='timestamp without time zone'::regtype then date_on::timestamp at time zone p_timezone else date_on::timestamptz end at time zone 'UTC')::date utc_day,
   public.traffic_ai_parse_float(case when jsonb_typeof(data::jsonb)='object' then data::jsonb->'Загальна сума' else null end) revenue
  from public.acts where case when pg_typeof(date_on)='timestamp without time zone'::regtype then date_on::timestamp>=p_since at time zone 'UTC' else date_on::timestamptz>=p_since end
 ), days as (
  select dow,count(*) count,count(distinct utc_day) dates,sum(revenue order by date_on,act_id) revenue from source group by dow
 ), hours as(select "hour",count(*) count from source group by "hour")
 select jsonb_build_object('complete',true,'total', (select count(*) from source),
  'days',coalesce((select jsonb_agg(to_jsonb(days) order by dow) from days),'[]'::jsonb),
  'hours',coalesce((select jsonb_agg(to_jsonb(hours) order by "hour") from hours),'[]'::jsonb));
$$;
revoke all on function public.traffic_ai_workload(timestamptz,text) from public;
grant execute on function public.traffic_ai_workload(timestamptz,text) to anon,authenticated;


-- SOURCE: 20261011140000_traffic_directories.sql

create or replace function public.traffic_directory_name(v text) returns text
language sql immutable security invoker set search_path=pg_catalog as $$
 select lower(btrim(regexp_replace(normalize(coalesce(v,''),NFKC),'[[:space:]]+',' ','g')));
$$;
create or replace function public.traffic_directory_page(p_kind text,p_query text default '',p_offset integer default 0,p_exact boolean default false,p_id bigint default null)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare id_col text; result jsonb; projection text; label text;
begin
 id_col:=case p_kind when 'slyusars' then 'slyusar_id' when 'incomes' then 'income_id' when 'receivers' then 'receiver_id' when 'faktura' then 'faktura_id' end;
 if id_col is null or p_offset<0 then raise exception 'Invalid directory';end if;
 if p_kind='faktura' then
  projection:='jsonb_build_object(''faktura_id'',t.faktura_id,''name'',t.name,''oderjyvach'',t.oderjyvach,''prumitka'',t.prumitka,''data'',t.data,''namber'',t.namber)';
  label:='coalesce(t.oderjyvach,'''')';
 else
  projection:=format('jsonb_build_object(%L,t.%I,''data'',(select coalesce(jsonb_object_agg(key,value),''{}''::jsonb) from jsonb_each(public.sto_read_object_v1(to_jsonb(t.data))) where key=any(%L::text[])))',id_col,id_col,
   case when p_kind='slyusars' then case when p_id is null then '{Name,Доступ,ПроцентРоботи,ПроцентЗапчастин,Склад}' else '{Name,Доступ,ПроцентРоботи,ПроцентЗапчастин,Склад,Пароль}' end else '{Name}' end);
  label:='coalesce(public.sto_read_object_v1(to_jsonb(t.data))->>''Name'','''')';
 end if;
 execute format('with matches as materialized (select t.%I id,%s row,%s label from public.%I t where ($4 is null or t.%I=$4) and (case when $3 then public.traffic_directory_name(%s)=public.traffic_directory_name($1) else strpos(public.traffic_directory_name(%s),public.traffic_directory_name($1))>0 end)),page as (select * from matches order by label,id offset $2 limit 50) select jsonb_build_object(''items'',coalesce((select jsonb_agg(row order by label,id) from page),''[]''::jsonb),''total'',(select count(*) from matches))',id_col,projection,label,p_kind,id_col,label,label)
 into result using p_query,p_offset,p_exact,p_id;
 return result;
end $$;

create or replace function public.traffic_employee_counts() returns jsonb
language sql stable security invoker set search_path=pg_catalog,public as $$
 select coalesce(jsonb_object_agg(role,n),'{}'::jsonb) from (
  select coalesce(nullif(public.sto_read_object_v1(to_jsonb(data))->>'Доступ',''),'Невідомо') role,count(*) n from public.slyusars group by 1
 ) s;
$$;

revoke all on function public.traffic_directory_page(text,text,integer,boolean,bigint),public.traffic_employee_counts() from public;
grant execute on function public.traffic_directory_page(text,text,integer,boolean,bigint),public.traffic_employee_counts() to anon,authenticated;


-- SOURCE: 20261011150000_traffic_ai_operational.sql
-- Compact Atlas operational reads over existing tables. No writes/new tables.
create or replace function public.traffic_ai_body(v jsonb)
returns jsonb language sql immutable security invoker set search_path=pg_catalog as $$
 select case when jsonb_typeof(v)='object' then v else '{}'::jsonb end;
$$;
create or replace function public.traffic_ai_operational(p_mode text,p_args jsonb default '{}')
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
#variable_conflict use_column
declare result jsonb; items jsonb:='[]'; groups jsonb:='{}'; info jsonb; d jsonb; r record; cid text; date_value timestamptz;
 now_value timestamptz:=coalesce((p_args->>'now')::timestamptz,now()); tz text:=coalesce(p_args->>'timezone','Europe/Kyiv');
 car bigint:=(p_args->>'car')::bigint; excluded bigint:=coalesce((p_args->>'exclude')::bigint,0);
 offset_value integer:=greatest(coalesce((p_args->>'offset')::integer,0),0);
 limit_value integer:=least(greatest(coalesce((p_args->>'limit')::integer,50),1),200);
 name_value text; needle text; total bigint; total_sum double precision; latest jsonb;
begin
 if p_mode='recommend' then
  with loads as (
   select public.traffic_ai_body(to_jsonb(data))->>'Слюсар' name,count(*) count from public.acts where date_off is null group by 1
  ) select coalesce(jsonb_agg(jsonb_build_object('slyusar_id',s.slyusar_id,'post_sluysar',s.post_sluysar,
    'data',jsonb_build_object('Name',d->'Name','Спеціалізація',d->'Спеціалізація','Рейтинг',d->'Рейтинг'),'current_load',coalesce(l.count,0)) order by s.slyusar_id),'[]') into items
   from public.slyusars s cross join lateral (select public.traffic_ai_body(to_jsonb(s.data)) d)x left join loads l on l.name=d->>'Name';
  result:=jsonb_build_object('items',items,'total',jsonb_array_length(items),'has_more',false);
 elsif p_mode in ('maintenance','vehicle') then
  -- Search the complete VIN/car history before choosing latest matching maintenance acts.
  with car_ids as (
   select car id union select cars_id from public.cars where length(btrim(coalesce(p_args->>'vin','')) )>=5
    and public.traffic_ai_body(to_jsonb(data))->>'Vincode'=btrim(p_args->>'vin')
  ), source as materialized (
   select act_id,date_on,date_off,public.traffic_ai_body(to_jsonb(data)) d from public.acts
    where cars_id in(select id from car_ids) and act_id<>excluded
  ), checks as(select value keywords,ordinality-1 idx from jsonb_array_elements(coalesce(p_args->'checks','[]')) with ordinality), matches as (
   select c.idx,a.act_id,a.date_on,a.date_off,a.d from checks c cross join lateral (
    select * from source s where exists(select 1 from jsonb_array_elements(case when jsonb_typeof(s.d->'Роботи')='array' then s.d->'Роботи' else '[]' end)w,
     jsonb_array_elements_text(c.keywords)k where strpos(lower(coalesce(w->>'Робота','')),lower(k))>0)
    order by date_on desc nulls first,act_id desc limit 1
   )a
  ) select (select count(*) from source),coalesce((select sum(public.traffic_ai_parse_float(d->'Загальна сума') order by date_on desc,act_id desc) from source),0),
   coalesce((select jsonb_agg(jsonb_build_object('index',idx,'act_id',act_id,'date_on',date_on,'date_off',date_off,'mileage',d->'Пробіг') order by idx) from matches),'[]'),
   coalesce((select jsonb_agg(row order by date_on desc nulls first,act_id desc) from (
    select act_id,date_on,jsonb_build_object('act_id',act_id,'date_on',date_on,'date_off',date_off,'mileage',d->'Пробіг','total_sum',public.traffic_ai_parse_float(d->'Загальна сума'),
     'works',coalesce((select jsonb_agg(w->>'Робота') from jsonb_array_elements(case when jsonb_typeof(d->'Роботи')='array' then d->'Роботи' else '[]' end)w where coalesce(w->>'Робота','')<>''),'[]'),
     'details',coalesce((select jsonb_agg(w->>'Деталь') from jsonb_array_elements(case when jsonb_typeof(d->'Деталі')='array' then d->'Деталі' else '[]' end)w where coalesce(w->>'Деталь','')<>''),'[]')) row
    from source where p_mode='vehicle' order by date_on desc nulls first,act_id desc offset offset_value limit limit_value
   )p),'[]') into total,total_sum,latest,items;
  result:=jsonb_build_object('items',items,'latest',latest,'total',total,'total_sum',total_sum,'has_more',p_mode='vehicle' and total>offset_value+limit_value,'next_offset',offset_value+limit_value);
 elsif p_mode='inactive' then
  -- Preserve legacy descending-created traversal and last-visit contact fallback rules.
  for r in select act_id,client_id,date_on,date_off,data from public.acts where client_id is not null order by date_on desc nulls first,act_id desc loop
   d:=public.traffic_ai_body(to_jsonb(r.data));cid:=r.client_id::text;
   date_value:=case when pg_typeof(r.date_on)='timestamp without time zone'::regtype then coalesce(r.date_off,r.date_on)::timestamp at time zone tz else coalesce(r.date_off,r.date_on)::timestamptz end;
   info:=groups->cid;
   if info is null then
    info:=jsonb_build_object('date',date_value,'name',coalesce(nullif(d->>'ПІБ',''),'—'),'phone',coalesce(nullif(d->>'Телефон',''),'—'),'totalActs',1,
      'totalSum',public.traffic_ai_parse_float(d->'Загальна сума'),'lastCar',coalesce(nullif(btrim(coalesce(d->>'Марка','')||' '||coalesce(d->>'Модель','')),''),nullif(d->>'Авто',''),'—'));
   else
    info:=info||jsonb_build_object('totalActs',(info->>'totalActs')::bigint+1,'totalSum',(info->>'totalSum')::double precision+public.traffic_ai_parse_float(d->'Загальна сума'));
    if date_value>(info->>'date')::timestamptz then
     info:=info||jsonb_build_object('date',date_value,'name',coalesce(nullif(d->>'ПІБ',''),info->>'name'),'phone',coalesce(nullif(d->>'Телефон',''),info->>'phone'),
      'lastCar',coalesce(nullif(btrim(coalesce(d->>'Марка','')||' '||coalesce(d->>'Модель','')),''),nullif(d->>'Авто',''),info->>'lastCar'));
    end if;
   end if;
   groups:=jsonb_set(groups,array[cid],info);
  end loop;
  with inactive as (
   select key::bigint client_id,value info,floor(extract(epoch from now_value-(value->>'date')::timestamptz)/86400) days from jsonb_each(groups)
  ), matches as(select * from inactive where days>=greatest(coalesce((p_args->>'days')::integer,180),0))
  select (select count(*) from matches),coalesce((select jsonb_agg(row order by spent desc,client_id) from (
    select client_id,floor((info->>'totalSum')::double precision+0.5) spent,jsonb_build_object('client_id',client_id,'name',info->'name','phone',info->'phone',
     'last_visit',to_char((info->>'date')::timestamptz at time zone 'UTC','YYYY-MM-DD'),'days_since',days,'months_since',floor(days/30),'total_acts',info->'totalActs',
     'total_spent',floor((info->>'totalSum')::double precision+0.5),'last_car',info->'lastCar','loyalty',case when (info->>'totalActs')::bigint>=5 then '🌟 постійний' when (info->>'totalActs')::bigint>=2 then '🔄 повторний' else '🆕 разовий' end) row
    from matches order by spent desc,client_id offset offset_value limit limit_value
  )p),'[]') into total,items;
  result:=jsonb_build_object('items',items,'total',total,'has_more',total>offset_value+limit_value,'next_offset',offset_value+limit_value);
 elsif p_mode='achievements' then
  needle:=coalesce(p_args->>'name','');needle:=left(needle,greatest(3,length(needle)-2));
  select coalesce(to_jsonb(s)->>'Name',public.traffic_ai_body(to_jsonb(s.data))->>'Name') into name_value from public.slyusars s
   where coalesce(to_jsonb(s)->>'Name',public.traffic_ai_body(to_jsonb(s.data))->>'Name') ilike '%'||needle||'%' order by slyusar_id limit 1;
  if name_value is null then return jsonb_build_object('name',null,'complete',true,'as_of',now_value);end if;
  needle:=left(name_value,greatest(3,length(name_value)-2));
  with source as materialized (
   select act_id,date_on,date_off,public.traffic_ai_body(to_jsonb(data)) d,
    case when pg_typeof(date_on)='timestamp without time zone'::regtype then date_on::timestamp at time zone tz else date_on::timestamptz end opened,
    case when pg_typeof(date_off)='timestamp without time zone'::regtype then date_off::timestamp at time zone tz else date_off::timestamptz end closed
   from public.acts where public.traffic_ai_body(to_jsonb(data))->>'Слюсар' ilike '%'||needle||'%'
  ), clients as(select d->>'ПІБ' name,count(*) count from source where coalesce(d->>'ПІБ','')<>'' group by 1), recent as(
   select extract(epoch from closed-opened)/3600 hours from source where date_off is not null order by date_on desc nulls first,act_id desc limit 50
  ) select jsonb_build_object('name',name_value,'total_acts',count(*),'closed_acts',count(*) filter(where date_off is not null),
   'total_revenue',coalesce(sum(public.traffic_ai_parse_float(d->'Загальна сума') order by date_on desc,act_id desc) filter(where date_off is not null),0),
   'this_month',count(*) filter(where opened>=(p_args->>'month_start')::timestamptz),
   'today',count(*) filter(where left(date_on::text,10)=p_args->>'today'),
   'unique_clients',(select count(*) from clients),'loyal_clients',(select count(*) from clients where count>=3),
   'close_times',coalesce((select jsonb_agg(hours) from recent where hours>0 and hours<720),'[]'),
   'work_days',coalesce((select jsonb_agg(work_day) from (select distinct left(date_on::text,10) work_day from source where date_on>=(now_value at time zone tz)-interval '366 days')w),'[]')) into result from source;
 else raise exception 'Unknown Atlas operational mode';
 end if;
 return result||jsonb_build_object('complete',true,'as_of',now_value,'scope',p_mode);
end $$;
revoke all on function public.traffic_ai_body(jsonb),public.traffic_ai_operational(text,jsonb) from public;
grant execute on function public.traffic_ai_body(jsonb),public.traffic_ai_operational(text,jsonb) to anon,authenticated;
notify pgrst,'reload schema';


-- SOURCE: 20261011150000_traffic_ai_stock_alerts.sql
-- Filter before paging; healthy stock and unused price/status/notes stay on the server.
create or replace function public.traffic_ai_stock_alerts(p_threshold double precision default 2,p_offset integer default 0)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 with source as (
  select sclad_id,name,part_number,shops,
   coalesce(public.traffic_search_number(to_jsonb(kilkist_on)),0)-coalesce(public.traffic_search_number(to_jsonb(kilkist_off)),0) current_qty,
   coalesce((regexp_match(prumitka::text,U&'(?:min|мін|мин)[:[:space:]\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]*([0-9]+)','i'))[1]::double precision,p_threshold) threshold
  from public.sclad
 ), filtered as(select * from source where current_qty<=0 or current_qty<=threshold),
 page as(select * from filtered order by name,sclad_id offset greatest(coalesce(p_offset,0),0) limit 200)
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(page) order by name,sclad_id) from page),'[]'::jsonb),
  'total_stock',(select count(*) from source),'total_alerts',(select count(*) from filtered),
  'has_more',(select count(*) from filtered)>greatest(coalesce(p_offset,0),0)+200);
$$;
revoke all on function public.traffic_ai_stock_alerts(double precision,integer) from public;
grant execute on function public.traffic_ai_stock_alerts(double precision,integer) to anon,authenticated;


-- SOURCE: 20261011160000_traffic_ai_closed_acts.sql
-- Explicit full-history tools receive only their own fields, with an explicit end marker.
create or replace function public.traffic_ai_closed_act_page(p_mode text,p_offset integer default 0)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb;
begin
 if p_mode not in ('maintenance','retention') or p_mode is null then raise exception 'Unknown closed-act projection';end if;
 with source as (
  select act_id,cars_id,client_id,date_on,date_off,case when jsonb_typeof(data::jsonb)='object' then data::jsonb else '{}'::jsonb end body
  from public.acts where date_off is not null
  order by date_on desc,act_id desc offset greatest(coalesce(p_offset,0),0) limit 201
 ), page as(select * from source order by date_on desc,act_id desc limit 200), projected as (
  select act_id,cars_id,client_id,date_on,date_off,
   jsonb_strip_nulls(jsonb_build_object('ПІБ',body->'ПІБ','Телефон',body->'Телефон','Марка',body->'Марка','Модель',body->'Модель','Авто',body->'Авто'))
   || case when p_mode='retention' then jsonb_build_object('Загальна сума',body->'Загальна сума')
   else jsonb_build_object('Держ. номер',body->'Держ. номер','Пробіг',body->'Пробіг','Роботи',
    case when jsonb_typeof(body->'Роботи')='array' then
     coalesce((select jsonb_agg(case when jsonb_typeof(w)='object' then jsonb_build_object('Робота',w->'Робота') else w end order by ord)
      from jsonb_array_elements(body->'Роботи') with ordinality a(w,ord)),'[]'::jsonb)
    else body->'Роботи' end) end data from page
 ) select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(projected) order by date_on desc,act_id desc) from projected),'[]'::jsonb),
  'has_more',(select count(*)>200 from source)) into result;
 return result;
end $$;
revoke all on function public.traffic_ai_closed_act_page(text,integer) from public;
grant execute on function public.traffic_ai_closed_act_page(text,integer) to anon,authenticated;


-- SOURCE: 20261011160000_traffic_analytics_dashboard.sql
-- Read-only accounting dashboard operands/aggregates. No new tables.
create or replace function public.traffic_analytics_or(v jsonb,fallback jsonb default '0'::jsonb)
returns jsonb language sql immutable security invoker set search_path=pg_catalog,public as $$
 select case when public.traffic_search_truthy(v) then v else fallback end;
$$;
create or replace function public.traffic_analytics_add(a jsonb,b jsonb)
returns jsonb language plpgsql immutable security invoker set search_path=pg_catalog,public as $$
begin
 -- Existing formulas use JS +, including its string concatenation semantics.
 if jsonb_typeof(a) in ('string','array','object') or jsonb_typeof(b) in ('string','array','object') then
  return to_jsonb(public.traffic_search_string(a)||public.traffic_search_string(b));
 end if;
 return to_jsonb(public.traffic_search_number(a)+public.traffic_search_number(b));
end $$;
create or replace function public.traffic_analytics_date(v text,p_timezone text)
returns timestamptz language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare parts text[];y integer;m integer;d integer;
begin
 if v is null or v='' then return null;end if;
 -- Date-only ISO history keys use UTC in JS; timestamp-without-zone fields use
 -- the browser zone. In particular acts and vutratu are NOT timestamptz.
 if v ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
  parts:=string_to_array(v,'-');y:=parts[1]::integer;m:=parts[2]::integer;d:=parts[3]::integer;
  if m not between 1 and 12 or d not between 1 and 31 then return null;end if;
  return (make_date(y,m,1)+(d-1))::timestamp at time zone 'UTC';
 end if;
 if v !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ]' then return null;end if;
 if v ~ '(Z|[+-][0-9]{2}(:?[0-9]{2})?)$' then return v::timestamptz;end if;
 return v::timestamp at time zone p_timezone;
 exception when invalid_datetime_format or datetime_field_overflow then return null;
end $$;
create or replace function public.traffic_analytics_mechanics(p_from timestamptz default null,p_to timestamptz default null,p_timezone text default 'Europe/Kyiv')
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare staff record;body jsonb;day record;entry jsonb;rec jsonb;date_value timestamptz;
 acts_count integer;earned jsonb;salary jsonb;works_count integer;items jsonb:='[]'::jsonb;
begin
 if not exists(select 1 from pg_timezone_names where name=p_timezone) then raise exception 'Invalid timezone';end if;
 for staff in select slyusar_id,data from public.slyusars order by slyusar_id loop
  body:=staff.data::jsonb;
  if not public.traffic_search_truthy(body->'Name') or not public.traffic_search_truthy(body->'Історія') or body->>'Доступ'='Приймальник' then continue;end if;
  acts_count:=0;earned:='0';salary:='0';works_count:=0;
  if jsonb_typeof(body->'Історія') is distinct from 'object' then continue;end if;
  for day in select * from jsonb_each(body->'Історія') loop
   if p_from is not null or p_to is not null then
    date_value:=public.traffic_analytics_date(day.key,p_timezone);
    if date_value is null or date_value<p_from or date_value>p_to then continue;end if;
   end if;
   if jsonb_typeof(day.value) is distinct from 'array' then continue;end if;
   for entry in select value from jsonb_array_elements(day.value) loop
    if entry='null'::jsonb then raise exception 'Invalid analytics salary history entry';end if;
    acts_count:=acts_count+1;
    earned:=public.traffic_analytics_add(earned,public.traffic_analytics_or(entry->'СуммаРоботи'));
    if public.traffic_search_truthy(entry->'Записи') then
     if jsonb_typeof(entry->'Записи') is distinct from 'array' then raise exception 'Invalid analytics salary records';end if;
     works_count:=works_count+jsonb_array_length(entry->'Записи');
     for rec in select value from jsonb_array_elements(entry->'Записи') loop
      if rec='null'::jsonb then raise exception 'Invalid analytics salary record';end if;
      salary:=public.traffic_analytics_add(salary,public.traffic_analytics_or(rec->'Зарплата'));
     end loop;
    end if;
   end loop;
  end loop;
  if acts_count>0 then items:=items||jsonb_build_array(jsonb_build_object('name',body->'Name','actsCount',acts_count,'totalEarned',earned,'totalSalary',salary,
    'avgPerAct',floor(public.traffic_search_number(earned)/acts_count+0.5),'totalWorks',works_count));end if;
 end loop;
 select coalesce(jsonb_agg(value order by public.traffic_search_number(value->'totalEarned') desc,ord),'[]'::jsonb) into items from jsonb_array_elements(items) with ordinality x(value,ord);
 return jsonb_build_object('items',items,'complete',true,'as_of',statement_timestamp());
end $$;
revoke all on function public.traffic_analytics_or(jsonb,jsonb),public.traffic_analytics_add(jsonb,jsonb),public.traffic_analytics_date(text,text),public.traffic_analytics_mechanics(timestamptz,timestamptz,text) from public;
grant execute on function public.traffic_analytics_or(jsonb,jsonb),public.traffic_analytics_add(jsonb,jsonb),public.traffic_analytics_date(text,text),public.traffic_analytics_mechanics(timestamptz,timestamptz,text) to anon,authenticated;

do $$ begin
 if to_regprocedure('public.traffic_analytics_sum(jsonb)') is null then
  execute 'create aggregate public.traffic_analytics_sum(jsonb) (sfunc=public.traffic_analytics_add,stype=jsonb,initcond=''0'')';
 end if;
end $$;

create or replace function public.traffic_analytics_dashboard(p_from timestamptz default null,p_to timestamptz default null,p_timezone text default 'Europe/Kyiv',p_now timestamptz default now())
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb; heat_from timestamptz;heat_to timestamptz;
begin
 if not exists(select 1 from pg_timezone_names where name=p_timezone) then raise exception 'Invalid timezone';end if;
 heat_from:=date_trunc('day',coalesce(p_from,case when p_to is not null then p_to else p_now end) at time zone p_timezone
   -case when p_from is null then interval '14 days' else interval '0 days' end) at time zone p_timezone;
 heat_to:=((case when p_to is not null then p_to at time zone p_timezone
   when p_from is not null then p_from at time zone p_timezone+interval '14 days'
   else p_now at time zone p_timezone end)::date+1)::timestamp at time zone p_timezone;
 with source as materialized (
  select a.act_id,a.client_id,a.cars_id,a.date_on,a.date_off,(a.data is not null and a.data::jsonb<>'null'::jsonb) has_body,public.traffic_json_object(a.data::jsonb) body,
    public.traffic_analytics_date(a.date_on::text,p_timezone) opened,
    public.traffic_analytics_date(a.date_off::text,p_timezone) closed
  from public.acts a
 ), acts as materialized (
  select *,row_number() over(order by date_on desc,act_id) rank,
    public.traffic_analytics_add(public.traffic_analytics_or(body->'За роботу'),public.traffic_analytics_or(body->'За деталі')) revenue
  from source
  where body->'Заморожений' is distinct from 'true'::jsonb
    and (p_from is null or coalesce(closed,opened)>=p_from) and (p_to is null or coalesce(closed,opened)<=p_to)
 ), works as materialized (
  select a.act_id,a.rank,w.ord,w.item,
   public.traffic_search_trim(w.item->>'Робота') name,
   public.traffic_search_number(public.traffic_analytics_or(w.item->'Ціна'))*
    public.traffic_search_number(public.traffic_analytics_or(w.item->'Кількість','1')) amount
  from acts a cross join lateral jsonb_array_elements(case when jsonb_typeof(a.body->'Роботи')='array' then a.body->'Роботи' else '[]' end) with ordinality w(item,ord)
 ), parts as materialized (
  select a.rank,d.ord,public.traffic_search_trim(d.item->>'Деталь') name,
    public.traffic_analytics_or(d.item->'Кількість','1') qty,
    public.traffic_search_number(public.traffic_analytics_or(d.item->'Ціна'))*
    public.traffic_search_number(public.traffic_analytics_or(d.item->'Кількість','1')) amount
  from acts a cross join lateral jsonb_array_elements(case when jsonb_typeof(a.body->'Деталі')='array' then a.body->'Деталі' else '[]' end) with ordinality d(item,ord)
 ), expense_rows as materialized (
  select v.vutratu_id,v.suma,v.act,public.traffic_analytics_date(v."dataOnn"::text,p_timezone) date_value
  from public.vutratu v
 ), expense_months as (
  select to_char(date_value at time zone p_timezone,'YYYY-MM') AS month,
    coalesce(sum(abs(suma::double precision) order by date_value desc,vutratu_id) filter(where suma<0),0) expenses
  from expense_rows where (act is null or act=0) and date_value is not null
    and (p_from is null or date_value>=p_from) and (p_to is null or date_value<=p_to) group by 1
 ), act_months as (
  select to_char(closed at time zone p_timezone,'YYYY-MM') AS month,
    public.traffic_analytics_sum(revenue order by rank) revenue,count(*) acts_count
  from acts where closed is not null group by 1
 ), months as (
  select coalesce(a.month,e.month) AS month,coalesce(a.revenue,'0'::jsonb) revenue,coalesce(e.expenses,0) expenses,
   public.traffic_search_number(coalesce(a.revenue,'0'))-coalesce(e.expenses,0) profit,coalesce(a.acts_count,0) acts_count
  from act_months a full join expense_months e using(month)
  order by 1 desc limit 12
 ), work_groups as (
  select name,sum(amount order by rank,ord) total,count(*) count,min(rank*1000000+ord) rank
  from works where coalesce(name,'')<>'' group by name
 ), part_groups as (
  select name,sum(amount order by rank,ord) total,public.traffic_analytics_sum(qty order by rank,ord) qty,count(*) count,min(rank*1000000+ord) rank
  from parts where coalesce(name,'')<>'' group by name
 ), category_rules as (
  select item->>0 name,item->1 keywords,ord from jsonb_array_elements('[["Ходова",["важіль","амортизатор","сайлентблок","тяга","наконечник","кульова","підшипник","пружина","втулка","стійка","ходова","кулак","балка","развал","сход"]],["Двигун",["двигун","гзм","грм","масло","фільтр","прокладка","сальник","свічки","клапан","головка","циліндр","поршень","ремен","ланцюг","турбіна","гбц"]],["Гальмівна",["гальм","колодки","диск","супорт","шланг","циліндр гальм","абс","abs","ручник"]],["Трансмісія",["кпп","акпп","зчеплення","демпфер","шрус","піввісь","редуктор","кардан","масло кпп"]],["Електрика",["світло","фара","ламп","провод","датчик","стартер","генератор","акумулятор","діагностика","комп","електри"]],["ТО",["діагностика","огляд","перевірка","то-","технічне обслуговування","фільтр повітр","фільтр палив"]],["Вихлопна",["глушник","резонатор","каталізатор","зварювання","гофра"]],["Охолодження",["радіатор","помпа","термостат","антифриз","патрубок","вентилятор"]]]'::jsonb) with ordinality c(item,ord)
 ), category_groups as (
  select coalesce(c.name,'Інше') name,sum(w.amount order by w.rank,w.ord) total,min(w.rank*1000000+w.ord) rank
  from works w left join lateral (
   select name from category_rules c where exists(select 1 from jsonb_array_elements_text(c.keywords) k where position(k in lower(coalesce(w.item->>'Робота','')))>0) order by c.ord limit 1
  ) c on true group by coalesce(c.name,'Інше')
 ), client_groups as (
  select client_id,count(*) count,public.traffic_analytics_sum(revenue order by rank) total,min(rank) rank
  from acts where client_id is not null and client_id<>0 group by client_id
 ), car_groups as (
  select cars_id,count(*) count,public.traffic_analytics_sum(revenue order by rank) total,min(rank) rank
  from acts where cars_id is not null and cars_id<>0 group by cars_id
 ), client_top as (
  select * from (select g.*,row_number() over(order by public.traffic_search_number(total) desc,rank) by_sum,row_number() over(order by count desc,rank) by_count from client_groups g) x where by_sum<=10 or by_count<=10
 ), car_top as (
  select * from (select g.*,row_number() over(order by public.traffic_search_number(total) desc,rank) by_sum,row_number() over(order by count desc,rank) by_count from car_groups g) x where by_sum<=10 or by_count<=10
 ), client_labels as (
  select t.*,jsonb_build_object('clientId',t.client_id,'totalSum',t.total,'actsCount',t.count,
   'pib',public.traffic_analytics_or(public.traffic_json_object(c.data::jsonb)->'ПІБ','"Невідомий"')) item
  from client_top t left join public.clients c using(client_id)
 ), car_labels as (
  select t.*,jsonb_build_object('carsId',t.cars_id,'totalSum',t.total,'actsCount',t.count,
   'carName',public.traffic_analytics_or(public.traffic_json_object(c.data::jsonb)->'Авто','"Невідомо"'),
   'plate',public.traffic_analytics_or(public.traffic_json_object(c.data::jsonb)->'Номер авто','""')) item
  from car_top t left join public.cars c on c.cars_id=t.cars_id and c.is_deleted is distinct from true
 ), anomaly_candidates as (
  select 1 priority,a.rank,jsonb_build_object('kind','salary','actId',a.act_id,'value',public.traffic_analytics_or(a.body->'За роботу')) item
  from acts a where a.closed is not null and public.traffic_search_number(public.traffic_analytics_or(a.body->'За роботу'))>0
   and exists(select 1 from works w where w.act_id=a.act_id)
   and (select public.traffic_analytics_sum(public.traffic_analytics_or(w.item->'Зарплата') order by w.ord) from works w where w.act_id=a.act_id)='0'::jsonb
  union all select 2,rank,jsonb_build_object('kind','zero','actId',act_id) from acts where closed is not null and has_body and revenue='0'::jsonb
  union all select 3,rank,jsonb_build_object('kind','old','actId',act_id,'days',floor(extract(epoch from(p_now-opened))/86400))
   from acts where closed is null and opened < ((p_now at time zone p_timezone)-interval '30 days') at time zone p_timezone
 ), day_groups as (
  select extract(dow from coalesce(closed,opened) at time zone p_timezone)::integer AS day,count(*) count,public.traffic_analytics_sum(revenue order by rank) revenue
  from acts where coalesce(closed,opened) is not null group by 1
 )
 select jsonb_build_object(
  'complete',true,'formula_version',1,'as_of',statement_timestamp(),
  'min_date',(select min(date_on) from source),
  'monthly',coalesce((select jsonb_agg(jsonb_build_object('month',month,'revenue',revenue,'expenses',expenses,'profit',profit,'actsCount',acts_count) order by month) from months),'[]'::jsonb),
  'avg_check',coalesce((select jsonb_agg(jsonb_build_object('month',month,'avg',floor(public.traffic_search_number(revenue)/acts_count+0.5)) order by month) from (select * from act_months order by month desc limit 12)x),'[]'::jsonb),
  'top_works',coalesce((select jsonb_agg(jsonb_build_object('name',name,'totalRevenue',total,'count',count) order by total desc,rank) from (select * from work_groups order by total desc,rank limit 10)x),'[]'::jsonb),
  'categories',coalesce((select jsonb_agg(jsonb_build_object('name',name,'value',total) order by total desc,rank) from category_groups where total>0),'[]'::jsonb),
  'days',coalesce((select jsonb_agg(to_jsonb(g) order by day) from day_groups g),'[]'::jsonb),
  'parts_sum',coalesce((select jsonb_agg(jsonb_build_object('name',name,'totalSum',total,'totalQty',qty,'actsCount',count) order by total desc,rank) from(select * from part_groups order by total desc,rank limit 10)x),'[]'::jsonb),
  'parts_count',coalesce((select jsonb_agg(jsonb_build_object('name',name,'totalSum',total,'totalQty',qty,'actsCount',count) order by count desc,public.traffic_search_number(qty) desc,rank) from(select * from part_groups order by count desc,public.traffic_search_number(qty) desc,rank limit 10)x),'[]'::jsonb),
  'clients_sum',coalesce((select jsonb_agg(item order by by_sum) from client_labels where by_sum<=10),'[]'::jsonb),
  'clients_count',coalesce((select jsonb_agg(item order by by_count) from client_labels where by_count<=10),'[]'::jsonb),
  'cars_sum',coalesce((select jsonb_agg(item order by by_sum) from car_labels where by_sum<=10),'[]'::jsonb),
  'cars_count',coalesce((select jsonb_agg(item order by by_count) from car_labels where by_count<=10),'[]'::jsonb),
  'anomalies',coalesce((select jsonb_agg(item order by priority,rank) from(select * from anomaly_candidates order by priority,rank limit 20)x),'[]'::jsonb),
  'summary',jsonb_build_object(
   'totalActs',(select count(*) from acts),'openActs',(select count(*) from acts where closed is null),
   'closedCount',(select count(*) from acts where closed is not null),
   'avgCheck',(select coalesce(floor(public.traffic_search_number(public.traffic_analytics_sum(revenue order by rank))/nullif(count(*),0)+0.5),0) from acts where closed is not null),
   'maxAct',coalesce((select jsonb_build_object('id',act_id,'total',revenue) from acts where closed is not null and public.traffic_search_number(revenue)>0 order by public.traffic_search_number(revenue) desc,rank limit 1),'{"id":0,"total":0}'),
   'uniqueClients',(select count(distinct client_id) from acts where client_id is not null and client_id<>0),
   'avgDays',(select coalesce(floor(avg(greatest(0,extract(epoch from(closed-opened))/86400))*10+0.5)/10,0) from acts where opened is not null and closed is not null)),
  'mechanics',public.traffic_analytics_mechanics(p_from,p_to,p_timezone)->'items',
  'planning',coalesce((select jsonb_agg(jsonb_build_object('data_on',data_on,'data_off',data_off,'status',status) order by post_arxiv_id)
    from public.post_arxiv where data_on<heat_to and data_off>=heat_from and status is distinct from 'Скасовано'),'[]'::jsonb),
  'posts_count',(select count(*) from public.post_name)
 ) into result;
 return result;
end $$;
revoke all on function public.traffic_analytics_dashboard(timestamptz,timestamptz,text,timestamptz) from public;
grant execute on function public.traffic_analytics_sum(jsonb),public.traffic_analytics_dashboard(timestamptz,timestamptz,text,timestamptz) to anon,authenticated;



-- SOURCE: 20261012103601_traffic_stock_lazy_page.sql
-- Requires traffic_stock_pages; preserves RLS and existing tables.

create or replace function public.traffic_stock_page_v2(p_status text default null,p_from text default null,p_to text default null,p_query text default '',p_before bigint default null,p_limit integer default 20)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 with page as (
 select n.sclad_id,n.time_on,n.shops,n.part_number,n.name,n.kilkist_on,n.price,n."scladNomer",n.rahunok,n.akt,n.unit_measurement,n.statys,n.prumitka,n.xto_zamovuv,n.client_price
 from public.sclad n
 where (case when p_status='Прибула' then n.statys is null when p_status in ('Замовити','Замовлено') then n.statys=p_status else n.statys in ('Замовити','Замовлено') end)
 and (nullif(p_from,'') is null or n.time_on >= nullif(p_from,'')::timestamptz)
 and (nullif(p_to,'') is null or n.time_on <= nullif(p_to,'')::timestamptz)
 and (p_before is null or n.sclad_id<p_before)
 and (nullif(btrim(p_query),'') is null or strpos(lower(coalesce(n.part_number,'')),lower(btrim(p_query)))>0 or
 (public.traffic_catalog_key(p_query)<>'' and strpos(public.traffic_catalog_key(n.part_number),public.traffic_catalog_key(p_query))>0))
 order by n.sclad_id desc limit least(20,greatest(1,coalesce(p_limit,20)))+1
 ), visible as (select * from page order by sclad_id desc limit least(20,greatest(1,coalesce(p_limit,20))))
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(v) order by v.sclad_id desc) from visible v),'[]'::jsonb),
 'has_more',(select count(*)>least(20,greatest(1,coalesce(p_limit,20))) from page),'next_cursor',(select min(sclad_id) from visible));
$$;



revoke all on function public.traffic_stock_page_v2(text,text,text,text,bigint,integer) from public;
grant execute on function public.traffic_stock_page_v2(text,text,text,text,bigint,integer) to anon,authenticated;
notify pgrst,'reload schema';


-- SOURCE: 20261012131746_traffic_payroll_report_timeout.sql
-- Payroll report timeout fix. Install after traffic_payroll_report.
-- Existing tables, RLS, formulas, page size and write guards are preserved.

-- Check the entire selected history, including duplicates outside the requested
-- dates, without repeatedly searching and copying a growing seen[] array.
create or replace function public.traffic_payroll_validate(p_data jsonb)
returns boolean language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare
 history jsonb:=coalesce(nullif(p_data->'Історія','null'::jsonb),'{}'::jsonb);
 missing_act boolean; invalid_records boolean; duplicate_act text; duplicate_record_act text;
begin
 if jsonb_typeof(history) is distinct from 'object' then raise exception 'Некоректна історія зарплат';end if;
 if exists(select 1 from jsonb_each(history) h where jsonb_typeof(h.value) is distinct from 'array') then
  raise exception 'Некоректна дата історії зарплат';
 end if;
 with entries as materialized (
  select x.value entry from jsonb_each(history) h cross join lateral jsonb_array_elements(h.value) x
 )
 select exists(select 1 from entries e where e.entry->>'Акт' is null),
  (select e.entry->>'Акт' from entries e group by e.entry->>'Акт' having count(*)>1 limit 1),
  exists(select 1 from entries e where e.entry?'Записи' and e.entry->'Записи'<>'null'::jsonb
   and jsonb_typeof(e.entry->'Записи') is distinct from 'array')
 into missing_act,duplicate_act,invalid_records;
 if missing_act then raise exception 'Нарахування без номера акта';end if;
 if duplicate_act is not null then raise exception 'Дублікати зарплати за актом %',duplicate_act;end if;
 if invalid_records then raise exception 'Некоректний список робіт';end if;
 select x.value->>'Акт' into duplicate_record_act
 from jsonb_each(history) h cross join lateral jsonb_array_elements(h.value) x
 cross join lateral jsonb_array_elements(coalesce(nullif(x.value->'Записи','null'::jsonb),'[]'::jsonb)) r
 where nullif(r.value->>'recordId','') is not null
 group by x.value->>'Акт',r.value->>'recordId' having count(*)>1 limit 1;
 if duplicate_record_act is not null then raise exception 'Повторні ідентифікатори робіт в акті %',duplicate_record_act;end if;
 return true;
end $$;

create or replace function public.traffic_payroll_report_optimized(
 p_filters jsonb,p_offset integer default 0,p_options boolean default true)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare
 result jsonb;
 selected_name text:=coalesce(p_filters->>'name','');
 mode text:=coalesce(p_filters->>'mode','open');
 from_day text:=public.traffic_payroll_iso(p_filters->>'from');
 to_day text:=public.traffic_payroll_iso(p_filters->>'to');
begin
 if mode not in ('open','close','paid') then raise exception 'Невідомий режим дат';end if;
 if to_day='' then raise exception 'Потрібна кінцева дата звіту';end if;
 -- Keep validation global: a duplicate outside the date window must still block payment.
 perform public.traffic_payroll_validate(public.payroll_json_object(to_jsonb(s.data)))
 from public.slyusars s
 where selected_name='' or public.payroll_json_object(to_jsonb(s.data))->>'Name'=selected_name;

 with employee_docs as materialized (
  select s.slyusar_id id,public.payroll_json_object(to_jsonb(s.data)) doc from public.slyusars s
 ), employees as materialized (
  select * from employee_docs where selected_name='' or doc->>'Name'=selected_name
 ), history_days as materialized (
  select e.id,e.doc->>'Name' name,e.doc->'ПроцентРоботи' percent,
   h.key history_day,h.value bucket,public.traffic_payroll_iso(h.key) history_iso
  from employees e cross join lateral jsonb_each(coalesce(nullif(e.doc->'Історія','null'::jsonb),'{}'::jsonb)) h
 ), selected_days as materialized (
  -- Opening dates belong to history buckets. Filter them before expanding acts or works.
  select * from history_days where mode<>'open' or
   (history_iso<>'' and (from_day='' or history_iso>=from_day) and history_iso<=to_day)
 ), raw_entries as materialized (
  select d.id,d.name,d.percent,d.history_day,d.history_iso,x.value entry,x.ordinality entry_order,
   x.value->>'Акт' act,
   -- Cast the history value, never the indexed acts.act_id. Canonical text matching
   -- retains the old behavior for malformed, padded or out-of-range legacy IDs.
   case when x.value->>'Акт' ~ '^(0|[1-9][0-9]{0,18}|-[1-9][0-9]{0,18})$' then
    case when (x.value->>'Акт')::numeric between -9223372036854775808 and 9223372036854775807
     then (x.value->>'Акт')::bigint end end act_number
  from selected_days d cross join lateral jsonb_array_elements(d.bucket) with ordinality x
 ), act_ids as materialized (
  select distinct act_number from raw_entries where act_number is not null
 ), act_docs as materialized (
  -- Parse each referenced act once, even if several employees worked on it.
  select a.act_id,a.date_off,parsed.doc->'Заморожений'='true'::jsonb frozen,
   parsed.doc->'__payroll_pending'='true'::jsonb pending
  from act_ids i join public.acts a on a.act_id=i.act_number
  -- Keep one evaluation of the parser, but materialize only two flags, not act JSON.
  cross join lateral (select public.payroll_json_object(to_jsonb(a.data)) doc offset 0) parsed
 ), entries as materialized (
  select r.*,a.act_id existing_act_id,a.date_off,
   a.frozen,a.pending,
   case when a.act_id is not null then coalesce(a.date_off::text,'') else coalesce(r.entry->>'ДатаЗакриття','') end close_day,
   case when a.act_id is not null then a.date_off is not null else coalesce(r.entry->>'ДатаЗакриття','')<>'' end closed
  from raw_entries r left join act_docs a on a.act_id=r.act_number
 ), scoped_entries as materialized (
  -- Closing dates cannot be inferred from opening dates. Filter their effective
  -- act/legacy date after the join, but still before expanding works.
  select * from entries where not coalesce(frozen,false) and
   (mode<>'close' or (public.traffic_payroll_iso(close_day)<>''
    and (from_day='' or public.traffic_payroll_iso(close_day)>=from_day)
    and public.traffic_payroll_iso(close_day)<=to_day))
 ), expanded as (
  select e.*,case when jsonb_array_length(coalesce(nullif(entry->'Записи','null'::jsonb),'[]'::jsonb))>0 then 'work'
   when entry?'СуммаРоботи' then 'receiver' when entry?'СуммаЗапчастин' then 'parts' else 'unknown' end kind,
   r.value row_data,r.ordinality::integer-1 work_index
  from scoped_entries e cross join lateral jsonb_array_elements(
   case when jsonb_array_length(coalesce(nullif(entry->'Записи','null'::jsonb),'[]'::jsonb))>0
    then entry->'Записи' else '[null]'::jsonb end) with ordinality r
 ), dated_rows as (
  select e.*,d.paid_day,
   case when kind='work' then coalesce(row_data->>'Робота','') when kind='receiver' then '-' else 'Запчастини' end work,
   case when mode='paid' then public.traffic_payroll_iso(d.paid_day)
    when mode='close' then public.traffic_payroll_iso(close_day) else history_iso end filter_day
  from expanded e cross join lateral (
   select case when kind='work' then coalesce(row_data->>'Розраховано','') else coalesce(entry->>'Розраховано','') end paid_day
  ) d
  where kind<>'unknown' and not(kind='work' and coalesce(row_data->'Кількість'='0'::jsonb,false)
   and not public.traffic_search_truthy(row_data->'Зарплата'))
 ), value_rows as materialized (
  -- Store scalar report values only. Do not copy the complete act/work JSON into
  -- every expanded row of the materialized totals/sort pipeline.
  select id,name,percent,history_day,history_iso,entry_order,act,existing_act_id,date_off,closed,pending,
   kind,work_index,paid_day,work,
   coalesce(public.traffic_search_number(row_data->'Ціна'),0)*coalesce(public.traffic_search_number(row_data->'Кількість'),0) work_total,
   coalesce(public.traffic_search_number(row_data->'Зарплата'),0) work_salary,
   coalesce(public.traffic_search_number(entry->'СуммаРоботи'),0) work_sum,
   coalesce(public.traffic_search_number(entry->'СуммаЗапчастин'),0) parts_sum,
   coalesce(public.traffic_search_number(entry->'ЗарплатаРоботи'),0) receiver_work_salary,
   coalesce(public.traffic_search_number(entry->'ЗарплатаЗапчастин'),0) parts_salary
  from dated_rows where filter_day<>'' and (from_day='' or filter_day>=from_day) and filter_day<=to_day
 ), date_matches as materialized (
  select *,case when kind='work' then work_total when kind='receiver' then work_sum+parts_sum else parts_sum end revenue,
   case when kind='work' then work_salary when kind='receiver' then (case when work_sum>0 then receiver_work_salary else 0 end)+parts_salary
    else case when parts_sum>0 then parts_salary else 0 end end salary
  from value_rows
 ), matches as materialized (
  select * from date_matches where
   (coalesce(p_filters->>'act','')='' or act=p_filters->>'act')
   and (coalesce(p_filters->>'work','')='' or strpos(lower(work),lower(p_filters->>'work'))>0)
   and (coalesce(p_filters->>'payment','all')='all' or (p_filters->>'payment'='paid' and paid_day<>'') or (p_filters->>'payment'='unpaid' and paid_day=''))
   and (coalesce(p_filters->>'status','all')='all' or (p_filters->>'status'='closed' and closed) or (p_filters->>'status'='open' and not closed))
   and (coalesce(p_filters->>'percentage','all')='all' or (kind='work' and salary<>0 and coalesce(public.traffic_search_number(percent),0)<>0 and
    case when p_filters->>'percentage'='higher' then (case when revenue>0 then salary/revenue*100 else 0 end)>public.traffic_search_number(percent)
     else (case when revenue>0 then salary/revenue*100 else 0 end)<public.traffic_search_number(percent) end))
 ), page as materialized (
  select *,coalesce(substring(act from '^[-+]?[0-9]+')::numeric,0) sort_act,
   case when mode='paid' then public.traffic_payroll_iso(paid_day) else history_iso end sort_day
  from matches order by sort_act desc,sort_day desc,id,history_day,entry_order,work_index
  offset greatest(coalesce(p_offset,0),0) limit 50
 ), page_entries as (
  -- Full act fragments remain available for the existing guarded payroll writes.
  select distinct p.id,p.name,p.percent,p.history_day,r.entry,p.entry_order
  from page p join raw_entries r on r.id=p.id and r.history_day=p.history_day and r.entry_order=p.entry_order
 ), histories as (
  select id,name,percent,history_day,jsonb_agg(entry order by entry_order) entries
  from page_entries group by id,name,percent,history_day
 ), rows as (
  select id,jsonb_build_object('slyusar_id',id,'data',jsonb_build_object('Name',name,'ПроцентРоботи',percent,'Історія',jsonb_object_agg(history_day,entries))) row
  from histories group by id,name,percent
 ), totals as (
  select count(*) total,coalesce(sum(revenue),0) revenue,coalesce(sum(salary),0) salary from matches
 )
 select jsonb_build_object(
  'employees',coalesce((select jsonb_agg(row order by id) from rows),'[]'::jsonb),
  'keys',coalesce((select jsonb_agg(jsonb_build_array(id,history_day,act,case when kind='work' then work_index else null end)
   order by sort_act desc,sort_day desc,id,history_day,entry_order,work_index) from page),'[]'::jsonb),
  'statuses',coalesce((select jsonb_agg(jsonb_build_object('actId',id,'dateOff',date_off,'isClosed',closed,'isFrozen',false,'payrollPending',pending))
   from (select distinct existing_act_id::text id,date_off,closed,pending from page where existing_act_id is not null)s),'[]'::jsonb),
  'total',t.total,'revenue',t.revenue,'salary',t.salary,'has_more',t.total>greatest(coalesce(p_offset,0),0)+50,
  'acts',case when coalesce(p_options,true) then coalesce((select jsonb_agg(act order by coalesce(substring(act from '^[-+]?[0-9]+')::numeric,0) desc)
   from(select distinct act from date_matches)a),'[]'::jsonb) else '[]'::jsonb end,
  'works',case when coalesce(p_options,true) then coalesce((select jsonb_agg(work order by work)
   from(select distinct work from date_matches order by work limit 150)w),'[]'::jsonb) else '[]'::jsonb end
 ) into result from totals t;
 return result;
end $$;

